              </section>

              <section className="admin46-playbook">
                <div className="admin46-playbook-header">
                  <div>
                    <div className="admin46-eyebrow">Matched local playbook</div>
                    <h3>{primarySupportPlaybook?.title || 'General administrator triage'}</h3>
                  </div>
                  <button type="button" onClick={copyAdminSupportAnswer} className="admin46-secondary">Copy local plan</button>
                </div>
                <p className="admin46-cause">{primarySupportPlaybook?.likelyCause}</p>
                <div className="admin46-step-columns">
                  <div>
                    <h4>Check first</h4>
                    {(primarySupportPlaybook?.firstChecks || []).map((line, index) => <div key={index} className="admin46-step"><span>{index + 1}</span><p>{line}</p></div>)}
                  </div>
                  <div>
                    <h4>Repair order</h4>
                    {(primarySupportPlaybook?.fixSteps || []).map((line, index) => <div key={index} className="admin46-step is-repair"><span>{index + 1}</span><p>{line}</p></div>)}
                  </div>
                </div>
                <div className="admin46-do-not">
                  <strong>Do not touch yet</strong>
                  <div>{(primarySupportPlaybook?.doNot || []).map((line, index) => <span key={index}>{line}</span>)}</div>
                </div>
              </section>
            </main>

            <aside className="admin46-article-reader">
              {selectedAdminArticle ? (
                <>
                  <div className="admin46-eyebrow"><BookOpen size={12}/> {selectedAdminArticle.group}</div>
                  <h3>{selectedAdminArticle.title}</h3>
                  <div className="admin46-article-body">
                    {(selectedAdminArticle.body || []).map((line, index) => (
                      <div key={index}>
                        <span>{index + 1}</span>
                        <p>{line}</p>
                      </div>
                    ))}
                  </div>
                  <button type="button" onClick={() => { navigator.clipboard?.writeText((selectedAdminArticle.body || []).join('\n')); addToast('Copied', 'Manual article copied.'); }} className="admin46-secondary w-full">Copy article</button>
                </>
              ) : (
                <div className="admin46-empty">Choose an article from the index.</div>
              )}
            </aside>
          </div>
          </div>
        </div>
      )}
        </div>
      </div>
    </div>
  );
};

const ROLE_KEYWORDS = {
  Manager: ['manager','gm','owner','lead','supervisor'],
  Kitchen: ['cook','chef','kitchen','prep','dish'],
  Bar: ['bar','bartender'],
  Service: ['server','host','wait','expo','runner'],
};

const normalizeLaborRole = (role) => String(role || 'Unassigned').trim() || 'Unassigned';
const roleFilterKey = (role) => normalizeLaborRole(role).toLowerCase();
const parseFinanceAmount = (value) => Number.isFinite(parseFloat(value)) ? parseFloat(value) : 0;
const moneyText = (value, digits = 0) => `$${parseFinanceAmount(value).toLocaleString(undefined, { minimumFractionDigits: digits, maximumFractionDigits: digits })}`;
const pctText = (value, digits = 1) => `${(Number.isFinite(parseFloat(value)) ? parseFloat(value) : 0).toFixed(digits)}%`;
const safeFinanceDate = (item = {}) => item.date || item.businessDate || item.invoiceDate || item.createdAt?.slice?.(0, 10) || '';
const getFinancialGrossSales = (item = {}) => parseFinanceAmount(item.grossSales ?? item.netSales ?? item.amount ?? item.totalSales ?? item.sales);
const getFinancialNetSales = (item = {}) => {
  const stored = parseFinanceAmount(item.netSales);
  if (stored > 0) return stored;
  const gross = getFinancialGrossSales(item);
  return Math.max(0, gross - parseFinanceAmount(item.discounts) - parseFinanceAmount(item.comps) - parseFinanceAmount(item.refunds));
};
const getFinancialLaborCost = (item = {}) => parseFinanceAmount(item.laborCost);
const getFinancialFoodCost = (item = {}) => parseFinanceAmount(item.foodCost);
const getFinancialBeverageCost = (item = {}) => parseFinanceAmount(item.beverageCost);
const getFinancialExpenseAmount = (item = {}) => parseFinanceAmount(item.amount ?? item.total ?? item.extendedCost ?? item.invoiceTotal);
const getFinancialInvoiceAmount = (item = {}) => parseFinanceAmount(item.total ?? item.invoiceTotal ?? item.amount ?? item.grandTotal ?? item.subtotal);
const FINANCE_SALES_CATEGORIES = [
  ['foodSales', 'Food'], ['liquorSales', 'Liquor'], ['beerSales', 'Beer'], ['wineSales', 'Wine'], ['beverageSales', 'NA Bev'], ['specialsSales', 'Specials'], ['cateringSales', 'Catering'], ['otherSales', 'Other']
];
const FINANCE_EXPENSE_CATEGORIES = ['Food', 'Liquor / Beer / Wine', 'Payroll', 'Rent', 'Utilities', 'Repairs & Maintenance', 'Supplies', 'Marketing', 'Fees', 'Insurance', 'Technology', 'Other'];
const FINANCE_PAYMENT_METHODS = ['Unpaid', 'Cash', 'Card', 'ACH', 'Check', 'Auto Pay', 'Owner Paid', 'Other'];
const FINANCE_DEPOSIT_STATUSES = ['Not Prepared', 'Prepared', 'Deposited', 'Verified'];
const FINANCE_CLOSE_STATUSES = ['Open', 'Manager Reviewed', 'Locked'];
const FINANCE_CLOSE_NUMERIC_FIELDS = [
  'grossSales', 'netSales', 'cashSales', 'cardSales', 'giftCardSales', 'discounts', 'comps', 'refunds', 'salesTax',
  'foodSales', 'liquorSales', 'beerSales', 'wineSales', 'beverageSales', 'specialsSales', 'cateringSales', 'otherSales',
  'laborCost', 'foodCost', 'beverageCost', 'tipsPaidOut', 'startingBank', 'cashPaidOut', 'cashCounted', 'depositAmount',
  'expectedCash', 'cashVariance', 'categorySalesTotal', 'estimatedProfit'
];
const validateFinanceClosePayload = (payload = {}) => {
  const restaurantId = String(payload.restaurantId || '').trim();
  if (!restaurantId || restaurantId.length > 160) return 'The restaurant identifier is invalid.';
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(payload.date || ''))) return 'The business date must use YYYY-MM-DD.';
  const invalidNumber = FINANCE_CLOSE_NUMERIC_FIELDS.find((field) => !Number.isFinite(payload[field]) || Math.abs(payload[field]) > 10000000);
  if (invalidNumber) return `${invalidNumber} must be a valid amount between -10,000,000 and 10,000,000.`;
  if (!FINANCE_DEPOSIT_STATUSES.includes(String(payload.depositStatus || ''))) return 'The deposit status is invalid.';
  if (!FINANCE_CLOSE_STATUSES.includes(String(payload.closeStatus || ''))) return 'The close status is invalid.';
  if (String(payload.managerSignOff || '').length > 120) return 'Manager sign-off must be 120 characters or fewer.';
  if (String(payload.notes || '').length > 2500) return 'Notes must be 2,500 characters or fewer.';
  if (String(payload.loggedBy || '').length > 200) return 'Logged-by text must be 200 characters or fewer.';
  if (String(payload.source || '').length > 80) return 'The financial close source is invalid.';
  return '';
};
const DEFAULT_FINANCE_TARGETS = { laborPct: 28, foodPct: 32, beveragePct: 22, primePct: 60, weeklySalesGoal: 0, monthlySalesGoal: 0, cashVarianceAlert: 10, overtimeAlertHours: 40 };
const financeAccess = (user = {}, perm = '') => Boolean(user?.isSuperAdmin || user?.isAdmin || user?.isOwner || user?.accountOwner || user?.owner || user?.workspaceOwner || user?.accountRole === 'owner' || (perm && user?.permissions?.[perm]));

const TabLabor = ({ currentDate, users = [], shifts = [], sales = [], timePunches = [], addToast, appUser }) => {
  const [subTab, setSubTab] = useState('fixer');
  const [rangeStart, setRangeStart] = useState(getWeekStart(currentDate));
  const [rangeEnd, setRangeEnd] = useState(getWeekDates(currentDate)[6]);
  const [employeeFilter, setEmployeeFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [roleFilter, setRoleFilter] = useState('all');
  const [exportMode, setExportMode] = useState('detail');
  const [editingPunch, setEditingPunch] = useState(null);
  const [form, setForm] = useState({ employeeId: '', date: getToday(), clockIn: '09:00', clockOut: '17:00', breakMinutes: '0', cashTips: '0', creditTips: '0', reason: 'Forgot to clock out', note: '' });

  const activeUsers = users.filter(u => u.isActive !== false).sort((a,b) => (a.name || '').localeCompare(b.name || ''));
  const dbRoles = useLiveCollection('roles', appUser?.restaurantId, { limitCount: 250 });
  const getLaborRole = (user = {}) => normalizeLaborRole(user.role);
  const configuredRoleNames = dbRoles.map(r => normalizeLaborRole(r.name)).filter(Boolean);
  const activeUserRoleNames = activeUsers.map(u => getLaborRole(u)).filter(Boolean);
  const roleOptions = Array.from(
    new Map([...configuredRoleNames, ...activeUserRoleNames].map(role => [roleFilterKey(role), role])).values()
  ).sort((a,b) => a.localeCompare(b));
  const selectedRoleLabel = roleFilter === 'all' ? 'Whole Restaurant' : (roleOptions.find(r => roleFilterKey(r) === roleFilter) || roleFilter);
  const userMatchesRole = (user = {}) => roleFilter === 'all' || roleFilterKey(getLaborRole(user)) === roleFilter;
  const filteredUsersForExport = activeUsers.filter(userMatchesRole);
  const visiblePunches = timePunches
    .filter(p => (p.date || '') >= rangeStart && (p.date || '') <= rangeEnd)
    .filter(p => { const emp = users.find(u => u.id === p.employeeId) || {}; return userMatchesRole(emp); })
    .filter(p => employeeFilter ? p.employeeId === employeeFilter : true)
    .filter(p => statusFilter === 'all' ? true : statusFilter === 'open' ? ['clocked_in','on_break'].includes(p.status) : statusFilter === 'exception' ? Boolean(getPunchIssue(p)) : p.status === statusFilter)
    .sort((a,b) => new Date(b.clockInTime || 0) - new Date(a.clockInTime || 0));

  function getPunchIssue(p) {
    if (!p) return '';
    if (['clocked_in','on_break'].includes(p.status)) return 'Still on clock';
    if (!p.clockInTime) return 'Missing clock-in';
    if (!p.clockOutTime && p.status !== 'clocked_in') return 'Missing clock-out';
    const hours = calculatePunchHours(p.clockInTime, p.clockOutTime, p.breakMinutes || 0);
    if (hours > 12) return 'Long shift, review break/punch';
    if (hours < 0) return 'Clock-out before clock-in';
    if (p.isUnscheduled && !p.isApproved) return 'Unscheduled punch needs approval';
    if (p.requiresManagerReview || ['outside','unverified','denied','unavailable'].includes(p.clockOutGeofenceStatus)) return 'Clock-out location needs review';
    return '';
  }

  const exceptionPunches = timePunches.filter(p => getPunchIssue(p)).sort((a,b) => new Date(b.clockInTime || 0) - new Date(a.clockInTime || 0));
  const rangeSales = sales.filter(s => (s.date || '') >= rangeStart && (s.date || '') <= rangeEnd).reduce((sum, s) => sum + getFinancialNetSales(s), 0);
  const payrollRows = visiblePunches.map(p => {
    const emp = users.find(u => u.id === p.employeeId) || {};
    const hours = calculatePunchHours(p.clockInTime, p.clockOutTime, p.breakMinutes || 0);
    return { punch: p, emp, role: getLaborRole(emp), hours, pay: hours * (parseFloat(emp.wage || 0) || 0), tips: (parseFloat(p.cashTips || 0) || 0) + (parseFloat(p.creditTips || 0) || 0), issue: getPunchIssue(p) };
  });
  const totalHours = payrollRows.reduce((s,r) => s + Math.max(0, r.hours), 0);
  const totalLabor = payrollRows.reduce((s,r) => s + Math.max(0, r.pay), 0);
  const totalTips = payrollRows.reduce((s,r) => s + r.tips, 0);
  const laborPct = rangeSales > 0 ? (totalLabor / rangeSales) * 100 : 0;

  const resetForm = () => {
    setEditingPunch(null);
    setForm({ employeeId: '', date: getToday(), clockIn: '09:00', clockOut: '17:00', breakMinutes: '0', cashTips: '0', creditTips: '0', reason: 'Forgot to clock out', note: '' });
  };

  const openEditPunch = (p) => {
    setEditingPunch(p);
    setForm({
      employeeId: p.employeeId || '',
      date: p.date || getToday(),
      clockIn: toLocalTimeInput(p.clockInTime) || '09:00',
      clockOut: toLocalTimeInput(p.clockOutTime) || new Date().toTimeString().slice(0,5),
      breakMinutes: String(Math.round(p.breakMinutes || 0)),
      cashTips: String(p.cashTips || 0),
      creditTips: String(p.creditTips || 0),
      reason: p.correctionReason || 'Manager correction',
      note: p.managerNote || ''
    });
    setSubTab('editor');
    setTimeout(() => document.getElementById('labor-editor')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
  };

  const savePunch = async (e) => {
    e.preventDefault();
    const emp = users.find(u => u.id === form.employeeId);
    if (!emp) return addToast('Missing Employee', 'Choose a team member before saving the punch.');
    if (!form.date || !form.clockIn) return addToast('Missing Time', 'Date and clock-in are required.');
    const payload = {
      restaurantId: appUser.restaurantId,
      employeeId: emp.id,
      employeeName: emp.name || emp.email || 'Unknown Staff',
      date: form.date,
      clockInTime: makeLocalIso(form.date, form.clockIn),
      clockOutTime: form.clockOut ? makeLocalIso(form.date, form.clockOut) : null,
      status: form.clockOut ? 'clocked_out' : 'clocked_in',
      breakMinutes: parseFloat(form.breakMinutes) || 0,
      cashTips: parseFloat(form.cashTips) || 0,
      creditTips: parseFloat(form.creditTips) || 0,
      isManual: true,
      isApproved: true,
      correctionReason: form.reason,
      managerNote: form.note,
      correctedBy: appUser.name || appUser.email || 'Manager',
      correctedById: appUser.id || 'unknown',
      correctedAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };
    try {
      if (editingPunch?.id) {
        await updateDoc(doc(db, 'timePunches', editingPunch.id), payload);
        await logAudit(appUser, 'EDIT_TIME_PUNCH', emp.name || emp.email, `${form.date} ${form.clockIn}-${form.clockOut || 'open'} reason: ${form.reason}`);
        addToast('Punch Updated', 'Time punch correction saved with audit details.');
      } else {
        await addDoc(collection(db, 'timePunches'), { ...payload, createdAt: new Date().toISOString(), createdBy: appUser.id || 'manager' });
        await logAudit(appUser, 'ADD_TIME_PUNCH', emp.name || emp.email, `${form.date} ${form.clockIn}-${form.clockOut || 'open'} reason: ${form.reason}`);
        addToast('Punch Added', 'Manual punch added and marked approved.');
      }
      resetForm();
      setSubTab('fixer');
    } catch (err) { addToast('Error', err.message); }
  };

  const forceOut = async (p) => {
    const now = new Date();
    try {
      await updateDoc(doc(db, 'timePunches', p.id), { clockOutTime: now.toISOString(), status: 'clocked_out', correctionReason: 'Manager force clock-out', correctedBy: appUser.name || appUser.email, correctedAt: now.toISOString(), isApproved: true });
      addToast('Clocked Out', `${p.employeeName || 'Employee'} was clocked out at ${formatClockTime(now)}.`);
    } catch (err) { addToast('Error', err.message); }
  };

  const approvePunch = async (p) => {
    try { await updateDoc(doc(db, 'timePunches', p.id), { isApproved: true, approvedBy: appUser.name || appUser.email, approvedAt: new Date().toISOString() }); addToast('Approved', 'Unscheduled punch approved.'); }
    catch (err) { addToast('Error', err.message); }
  };

  const deletePunch = async (p) => {
    if (!window.confirm(`Delete this punch for ${p.employeeName || 'employee'}? This should only be used for duplicate/bad entries.`)) return;
    try { await deleteDoc(doc(db, 'timePunches', p.id)); addToast('Deleted', 'Time punch removed.'); }
    catch (err) { addToast('Error', err.message); }
  };

  const buildLaborExport = () => {
    let rows;
    let exportName = 'time-punch-detail';
    let title = 'Time Punch Detail';

    if (exportMode === 'summary') {
      exportName = 'total-hours-summary';
      title = 'Total Hours Summary';
      const summaryMap = payrollRows.reduce((acc, r) => {
        const key = r.punch.employeeId || r.emp.id || r.punch.employeeName || 'unknown';
        if (!acc[key]) {
          acc[key] = {
            employee: r.emp.name || r.punch.employeeName || 'Unknown',
            role: r.role || 'Unassigned',
            hours: 0,
            pay: 0,
            cashTips: 0,
            creditTips: 0,
            tips: 0,
            punchCount: 0,
            issueCount: 0,
            reasons: new Set()
          };
        }
        const row = acc[key];
        row.hours += Math.max(0, r.hours || 0);
        row.pay += Math.max(0, r.pay || 0);
        row.cashTips += parseFloat(r.punch.cashTips || 0) || 0;
        row.creditTips += parseFloat(r.punch.creditTips || 0) || 0;
        row.tips += r.tips || 0;
        row.punchCount += 1;
        if (r.issue) row.issueCount += 1;
        if (r.punch.correctionReason) row.reasons.add(r.punch.correctionReason);
        return acc;
      }, {});

      rows = [['Employee','Role','Range Start','Range End','Total Hours','Pay Estimate','Cash Tips','Credit Tips','Total Tips','Punch Count','Issue Count','Reasons']];
      Object.values(summaryMap)
        .sort((a,b) => a.employee.localeCompare(b.employee))
        .forEach(r => rows.push([
          r.employee,
          r.role || 'Unassigned',
          rangeStart,
          rangeEnd,
          r.hours.toFixed(2),
          r.pay.toFixed(2),
          r.cashTips.toFixed(2),
          r.creditTips.toFixed(2),
          r.tips.toFixed(2),
          r.punchCount,
          r.issueCount,
          Array.from(r.reasons).join('; ')
        ]));
    } else {
      rows = [['Employee','Role','Date','Clock In','Clock Out','Break Minutes','Hours','Cash Tips','Credit Tips','Pay Estimate','Issue','Reason']];
      payrollRows.forEach(r => rows.push([
        r.emp.name || r.punch.employeeName || 'Unknown',
        r.role || 'Unassigned',
        r.punch.date || '',
        r.punch.clockInTime ? formatClockDateTime(r.punch.clockInTime, appUser) : '',
        r.punch.clockOutTime ? formatClockDateTime(r.punch.clockOutTime, appUser) : '',
        r.punch.breakMinutes || 0,
        r.hours.toFixed(2),
        r.punch.cashTips || 0,
        r.punch.creditTips || 0,
        r.pay.toFixed(2),
        r.issue,
        r.punch.correctionReason || ''
      ]));
    }

    const prefix = getRestaurantExportPrefix(appUser);
    const deptPart = roleFilter === 'all' ? 'whole-restaurant' : safeFilenamePart(selectedRoleLabel);
    const filenameBase = `${prefix}-${deptPart}-${exportName}-${rangeStart}-to-${rangeEnd}`;
    const subtitle = `${appUser?.restaurantName || 'Restaurant'} • ${selectedRoleLabel} • ${rangeStart} to ${rangeEnd} • ${payrollRows.length} punch${payrollRows.length === 1 ? '' : 'es'}`;
    return { rows, exportName, title, filenameBase, subtitle };
  };

  const exportCsv = () => {
    if (payrollRows.length === 0) return addToast('Empty', 'No labor records match the current filters.');
    const { rows, filenameBase } = buildLaborExport();
    downloadCsvRows(`${filenameBase}.csv`, rows);
    addToast('Exported', `${exportMode === 'summary' ? 'Total hours summary' : 'Time punch detail'} CSV downloaded.`);
  };

  const exportPdf = () => {
    if (payrollRows.length === 0) return addToast('Empty', 'No labor records match the current filters.');
    const { rows, title, filenameBase, subtitle } = buildLaborExport();
    const opened = openPrintableReport({ title: `${appUser?.restaurantName || 'Restaurant'} - ${title}`, subtitle, rows, filename: `${filenameBase}.pdf` });
    if (opened) addToast('PDF Ready', 'Print window opened. Choose Save as PDF or your printer.');
    else addToast('Popup Blocked', 'Allow popups for this site, then try PDF again.');
  };

  return (
    <div className="desktop-management-page max-w-7xl mx-auto space-y-4 pb-24">
      <div className={`${T.card} p-4 sm:p-5 cockpit-grid`}>
        <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-4">
          <div>
            <div className="text-[10px] font-black uppercase tracking-widest text-[#D4A381] mb-1">Manager Labor Console</div>
            <h2 className="text-2xl font-black text-white tracking-tight">Labor & Timesheets</h2>
            <p className="text-xs text-slate-400 font-bold mt-1 max-w-2xl">Punch Fixer, payroll review, tip totals, labor percentage, and export tools live here. Schedule Builder now handles planning; this tab handles what actually happened.</p>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 w-full lg:w-auto">
            <div className="bg-[#12161A] border border-[#2A353D] rounded-xl p-3"><div className="text-[9px] uppercase font-black text-slate-500">Hours</div><div className="text-lg font-black text-white">{totalHours.toFixed(1)}</div></div>
            <div className="bg-[#12161A] border border-[#2A353D] rounded-xl p-3"><div className="text-[9px] uppercase font-black text-slate-500">Labor</div><div className="text-lg font-black text-[#D4A381]">${totalLabor.toFixed(0)}</div></div>
            <div className="bg-[#12161A] border border-[#2A353D] rounded-xl p-3"><div className="text-[9px] uppercase font-black text-slate-500">Labor %</div><div className="text-lg font-black text-white">{rangeSales ? laborPct.toFixed(1)+'%' : '—'}</div></div>
            <div className="bg-[#12161A] border border-[#2A353D] rounded-xl p-3"><div className="text-[9px] uppercase font-black text-slate-500">Issues</div><div className={`text-lg font-black ${exceptionPunches.length ? 'text-amber-400' : 'text-emerald-400'}`}>{exceptionPunches.length}</div></div>
          </div>
        </div>
      </div>

      <div className="flex flex-wrap gap-2 border-b border-[#2A353D] pb-3">
        {[['fixer','Punch Fixer'],['editor', editingPunch ? 'Edit Punch' : 'Add Punch'],['review','Timesheet Review'],['tips','Tips'],['export','Export']].map(([id,label]) => <button key={id} onClick={() => setSubTab(id)} className={`px-3 py-2 rounded-xl text-[10px] uppercase tracking-widest font-black ${subTab === id ? `${T.grad} text-slate-900` : 'bg-[#1A2126] text-slate-400 hover:text-white'}`}>{label}</button>)}
      </div>

      <div className={`${T.card} p-3 flex flex-col md:flex-row gap-2 md:items-center justify-between`}>
        <div className="flex flex-wrap gap-2">
          <input type="date" value={rangeStart} onChange={e => setRangeStart(e.target.value)} className={`${T.input} py-2 text-xs w-auto`} />
          <input type="date" value={rangeEnd} onChange={e => setRangeEnd(e.target.value)} className={`${T.input} py-2 text-xs w-auto`} />
          <select value={roleFilter} onChange={e => { setRoleFilter(e.target.value); setEmployeeFilter(''); }} className={`${T.input} py-2 text-xs w-auto`}><option value="all">Whole Restaurant</option>{roleOptions.map(role => <option key={roleFilterKey(role)} value={roleFilterKey(role)}>{role}</option>)}</select>
          <select value={employeeFilter} onChange={e => setEmployeeFilter(e.target.value)} className={`${T.input} py-2 text-xs w-auto`}><option value="">All Staff</option>{filteredUsersForExport.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}</select>
          <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className={`${T.input} py-2 text-xs w-auto`}><option value="all">All Punches</option><option value="exception">Needs Attention</option><option value="open">Open / On Clock</option><option value="clocked_out">Closed</option></select>
        </div>
        <button onClick={() => { resetForm(); setSubTab('editor'); }} className={`${T.btn} py-2 text-xs flex items-center gap-2 justify-center`}><Plus size={15}/> Add Punch</button>
      </div>

      {subTab === 'fixer' && <div className="grid lg:grid-cols-3 gap-4">
        <div className="lg:col-span-1 space-y-3">
          <div className={`${T.card} p-4`}><div className="text-[10px] uppercase tracking-widest font-black text-[#D4A381] mb-2">Needs Attention</div>{exceptionPunches.length === 0 ? <div className="text-sm font-bold text-emerald-400 bg-emerald-900/10 border border-emerald-900/30 rounded-xl p-4">No punch fires right now. The time-clock goblin is asleep.</div> : exceptionPunches.slice(0, 12).map(p => <div key={p.id} className="bg-[#12161A] border border-amber-900/40 rounded-xl p-3 mb-2"><div className="font-black text-white text-sm">{p.employeeName || 'Unknown'}</div><div className="text-[10px] text-amber-400 font-black uppercase tracking-widest">{getPunchIssue(p)}</div><div className="text-xs text-slate-400 mt-1">{p.date ? formatDisplayDate(p.date) : 'No date'} • In {formatClockTime(p.clockInTime) || '—'} • Out {formatClockTime(p.clockOutTime) || '—'}</div><div className="flex gap-2 mt-2"><button onClick={() => openEditPunch(p)} className="flex-1 bg-[#1A2126] border border-[#2A353D] rounded-lg py-1.5 text-[10px] font-black text-slate-300 hover:text-[#D4A381]">Fix</button>{['clocked_in','on_break'].includes(p.status) && <button onClick={() => forceOut(p)} className="flex-1 bg-red-900/20 border border-red-900/50 rounded-lg py-1.5 text-[10px] font-black text-red-300">Clock Out</button>}{p.isUnscheduled && !p.isApproved && <button onClick={() => approvePunch(p)} className="flex-1 bg-amber-900/20 border border-amber-900/50 rounded-lg py-1.5 text-[10px] font-black text-amber-300">Approve</button>}</div></div>)}</div>
        </div>
        <div className="lg:col-span-2"><PunchTable rows={payrollRows} openEditPunch={openEditPunch} forceOut={forceOut} approvePunch={approvePunch} deletePunch={deletePunch} /></div>
      </div>}

      {subTab === 'editor' && <div id="labor-editor" className={`${T.card} p-4`}>
        <h3 className="font-black text-white text-lg mb-1">{editingPunch ? 'Edit Time Punch' : 'Add Manual Time Punch'}</h3>
        <p className="text-xs text-slate-400 font-bold mb-4">Simple manager correction form with reason and notes saved for the audit trail.</p>
        <form onSubmit={savePunch} className="grid md:grid-cols-2 gap-3">
          <div><label className={T.label}>Employee</label><select value={form.employeeId} onChange={e => setForm({...form, employeeId: e.target.value})} className={T.input} required><option value="">Choose employee</option>{activeUsers.map(u => <option key={u.id} value={u.id}>{u.name} • {u.role}</option>)}</select></div>
          <div><label className={T.label}>Date</label><input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} className={T.input} required /></div>
          <div><label className={T.label}>Clock In</label><input type="time" value={form.clockIn} onChange={e => setForm({...form, clockIn: e.target.value})} className={T.input} required /></div>
          <div><label className={T.label}>Clock Out</label><input type="time" value={form.clockOut} onChange={e => setForm({...form, clockOut: e.target.value})} className={T.input} /></div>
          <div><label className={T.label}>Break Minutes</label><input type="number" value={form.breakMinutes} onChange={e => setForm({...form, breakMinutes: e.target.value})} className={T.input} /></div>
          <div><label className={T.label}>Reason</label><select value={form.reason} onChange={e => setForm({...form, reason: e.target.value})} className={T.input}><option>Forgot to clock in</option><option>Forgot to clock out</option><option>System issue</option><option>Manager correction</option><option>Training</option><option>Manual entry</option><option>Other</option></select></div>
          <div><label className={T.label}>Cash Tips</label><input type="number" step="0.01" value={form.cashTips} onChange={e => setForm({...form, cashTips: e.target.value})} className={T.input} /></div>
          <div><label className={T.label}>Credit Tips</label><input type="number" step="0.01" value={form.creditTips} onChange={e => setForm({...form, creditTips: e.target.value})} className={T.input} /></div>
          <div className="md:col-span-2"><label className={T.label}>Manager Note</label><textarea value={form.note} onChange={e => setForm({...form, note: e.target.value})} className={T.input} rows="3" placeholder="Example: Jenna forgot to clock out after closing duties." /></div>
          <div className="md:col-span-2 flex gap-2"><button type="submit" className={`${T.btn} flex-1`}>{editingPunch ? 'Save Correction' : 'Add Punch'}</button><button type="button" onClick={resetForm} className={T.btnAlt}>Clear</button></div>
        </form>
      </div>}

      {subTab === 'review' && <PunchTable rows={payrollRows} openEditPunch={openEditPunch} forceOut={forceOut} approvePunch={approvePunch} deletePunch={deletePunch} />}
      {subTab === 'tips' && <div className={`${T.card} p-4`}><h3 className="font-black text-white mb-3">Tip Summary</h3><div className="grid md:grid-cols-3 gap-3"><div className="bg-[#12161A] border border-[#2A353D] rounded-xl p-4"><div className="text-[10px] uppercase text-slate-500 font-black">Cash Tips</div><div className="text-2xl font-black text-white">${payrollRows.reduce((s,r)=>s+(parseFloat(r.punch.cashTips||0)||0),0).toFixed(2)}</div></div><div className="bg-[#12161A] border border-[#2A353D] rounded-xl p-4"><div className="text-[10px] uppercase text-slate-500 font-black">Credit Tips</div><div className="text-2xl font-black text-white">${payrollRows.reduce((s,r)=>s+(parseFloat(r.punch.creditTips||0)||0),0).toFixed(2)}</div></div><div className="bg-[#12161A] border border-[#2A353D] rounded-xl p-4"><div className="text-[10px] uppercase text-slate-500 font-black">Total Tips</div><div className="text-2xl font-black text-[#D4A381]">${totalTips.toFixed(2)}</div></div></div></div>}
      {subTab === 'export' && <div className={`${T.card} p-5 space-y-4`}>
        <div>
          <h3 className="font-black text-white text-lg">Payroll Export</h3>
          <p className="text-xs text-slate-400 font-bold mt-1">Download the selected custom role or whole restaurant as a CSV or print-ready PDF for payroll review, accountant handoff, or owner records. Role choices come from the roles created in Settings, plus any active staff roles already in use.</p>
        </div>
        <div className="grid sm:grid-cols-2 gap-3 max-w-2xl">
          <button type="button" onClick={() => setExportMode('detail')} className={`text-left rounded-xl border p-4 transition-all ${exportMode === 'detail' ? 'border-[#D4A381] bg-[#D4A381]/10' : 'border-[#2A353D] bg-[#12161A] hover:border-[#D4A381]/50'}`}>
            <div className="text-sm font-black text-white">Time Punch Detail</div>
            <div className="text-[10px] text-slate-400 font-bold mt-1 uppercase tracking-widest">Every clock-in/clock-out row</div>
          </button>
          <button type="button" onClick={() => setExportMode('summary')} className={`text-left rounded-xl border p-4 transition-all ${exportMode === 'summary' ? 'border-[#D4A381] bg-[#D4A381]/10' : 'border-[#2A353D] bg-[#12161A] hover:border-[#D4A381]/50'}`}>
            <div className="text-sm font-black text-white">Total Hours Summary</div>
            <div className="text-[10px] text-slate-400 font-bold mt-1 uppercase tracking-widest">One row per employee</div>
          </button>
        </div>
        <div className="flex flex-col sm:flex-row gap-2"><button onClick={exportCsv} className={`${T.btn} flex items-center gap-2 justify-center`}><Package size={16}/> Download {exportMode === 'summary' ? 'Summary' : 'Punch Detail'} CSV</button><button onClick={exportPdf} className={`${T.btnAlt} flex items-center gap-2 justify-center`}><Package size={16}/> Print / Save PDF</button></div>
      </div>}
    </div>
  );
};

const HELP_ARTICLES = CUSTOMER_HELP_ARTICLES_LEGACY;


const HelpInlineText = ({ text = '', canOpenHelpLink, openHelpLink }) => {
  const parts = String(text || '').split(/(\[\[[^\]]+\|[^\]]+\]\])/g).filter(Boolean);
  return <>{parts.map((part, index) => {
    const match = part.match(/^\[\[([^|]+)\|([^\]]+)\]\]$/);
    if (!match) return <span key={index}>{part}</span>;
    const label = match[1];
    const id = match[2];
    if (!HELP_DEEP_LINKS[id]) return <span key={index}>{label}</span>;
    const allowed = canOpenHelpLink(id);
    return allowed ? <button key={index} type="button" onClick={() => openHelpLink(id)} className="text-[#D4A381] underline decoration-[#D4A381]/40 underline-offset-4 font-black hover:text-white focus:outline-none focus:ring-2 focus:ring-[#D4A381] rounded">{label}</button> : <span key={index} className="text-slate-200 font-black">{label}</span>;
  })}</>;
};

const TabHelpCenter = ({ appUser, activeTab, helpOrigin = '', voiceHelpSearchTarget = null, addToast, setActiveTab, setScheduleSubTabTarget, setInventorySubTabTarget }) => {
  const [query, setQuery] = useState('');
  const [selectedSubject, setSelectedSubject] = useState('');
  const [selectedSubtopic, setSelectedSubtopic] = useState('');
  const [selectedArticleId, setSelectedArticleId] = useState('');
  const [askQuestion, setAskQuestion] = useState('');
  const [askResult, setAskResult] = useState(null);
  const [askLoading, setAskLoading] = useState(false);
  const [askHistory, setAskHistory] = useState([]);
  const [bugText, setBugText] = useState('');
  const [bugCategory, setBugCategory] = useState('Bug / Error');
  const [isSubmittingBug, setIsSubmittingBug] = useState(false);
  const [feedbackOpen, setFeedbackOpen] = useState(false);
  const [feedbackText, setFeedbackText] = useState('');

  useEffect(() => {
    const applyHelpStateFromUrl = () => {
      const params = new URLSearchParams(window.location.search);
      const subject = params.get('helpSubject') || '';
      const subtopic = params.get('helpSubtopic') || '';
      const article = params.get('helpArticle') || '';
      setSelectedSubject(HELP_SUBJECTS.some(s => s.id === subject) ? subject : '');
      setSelectedSubtopic(HELP_SUBTOPICS.some(s => s.id === subtopic) ? subtopic : '');
      setSelectedArticleId(CUSTOMER_HELP_ARTICLES.some(a => a.id === article) ? article : '');
    };
    applyHelpStateFromUrl();
    window.addEventListener('popstate', applyHelpStateFromUrl);
    return () => window.removeEventListener('popstate', applyHelpStateFromUrl);
  }, []);

  useEffect(() => {
    const search = voiceHelpSearchTarget?.query;
    if (!search) return;
    setQuery(search);
    setAskQuestion(search);
    setSelectedSubject('');
    setSelectedSubtopic('');
    setSelectedArticleId('');
  }, [voiceHelpSearchTarget?.id]);

  const roleIsManager = Boolean(appUser?.isOwner || appUser?.owner || appUser?.accountOwner || appUser?.isAdmin || appUser?.permissions?.team || appUser?.permissions?.schedule || appUser?.permissions?.inventory || appUser?.permissions?.financials);
  const canOpenHelpLink = (id) => {
    const dest = HELP_DEEP_LINKS[id];
    if (!dest) return false;
    if (dest.audience === 'Manager / Owner' && !roleIsManager) return false;
    return true;
  };
  const pushHelpState = (patch = {}) => {
    const params = new URLSearchParams(window.location.search);
    params.set('tab', 'help');
    const next = { helpSubject: selectedSubject, helpSubtopic: selectedSubtopic, helpArticle: selectedArticleId, ...patch };
    ['helpSubject','helpSubtopic','helpArticle'].forEach(key => {
      if (next[key]) params.set(key, next[key]); else params.delete(key);
    });
    window.history.pushState({ tab: 'help', ...next }, '', `?${params.toString()}`);
  };
  const chooseSubject = (id) => { setSelectedSubject(id); setSelectedSubtopic(''); setSelectedArticleId(''); pushHelpState({ helpSubject: id, helpSubtopic: '', helpArticle: '' }); };
  const chooseSubtopic = (id) => { setSelectedSubtopic(id); setSelectedArticleId(''); pushHelpState({ helpSubtopic: id, helpArticle: '' }); };
  const chooseArticle = (id) => { setSelectedArticleId(id); pushHelpState({ helpArticle: id }); };
  const openHelpLink = (id) => {
    const dest = HELP_DEEP_LINKS[id];
    if (!dest) return;
    if (!canOpenHelpLink(id)) {
      const fallback = dest.fallbackArticleId || CUSTOMER_HELP_ARTICLES.find(a => (a.deepLinkIds || []).includes(id))?.id;
      if (fallback) chooseArticle(fallback);
      addToast?.('Manager or Owner Needed', `A manager or owner needs to check ${dest.label}.`);
      return;
    }
    if (dest.scheduleSubtab) setScheduleSubTabTarget?.({ id: dest.scheduleSubtab, source: 'help', at: Date.now() });
    if (dest.inventorySubtab) setInventorySubTabTarget?.(dest.inventorySubtab);
    setActiveTab?.(dest.tab || 'today');
  };

  const subject = HELP_SUBJECTS.find(s => s.id === selectedSubject) || null;
  const subtopics = useMemo(() => HELP_SUBTOPICS.filter(s => !selectedSubject || s.subjectId === selectedSubject), [selectedSubject]);
  const subtopic = HELP_SUBTOPICS.find(s => s.id === selectedSubtopic) || null;
  const article = CUSTOMER_HELP_ARTICLES.find(a => a.id === selectedArticleId) || null;
  const searchResults = useMemo(() => query.trim() ? searchCustomerHelp(query, { limit: 8 }) : [], [query]);
  const directAnswer = useMemo(() => query.trim() ? makeDeterministicHelpAnswer(query) : null, [query]);
  const coverage = useMemo(() => buildCustomerHelpCoverage(), []);
  const originSubject = useMemo(() => {
    const origin = String(helpOrigin || activeTab || '').toLowerCase();
    if (/schedule|published|time/.test(origin)) return HELP_SUBJECTS.find(s => s.id === 'schedule-time-clock');
    if (/inventory|menu/.test(origin)) return HELP_SUBJECTS.find(s => s.id === 'inventory-purchasing');
    if (/maintenance|events/.test(origin)) return HELP_SUBJECTS.find(s => s.id === 'maintenance-events');
    if (/financial|sales|labor/.test(origin)) return HELP_SUBJECTS.find(s => s.id === 'financials');
    if (/prep|recipes/.test(origin)) return HELP_SUBJECTS.find(s => s.id === 'recipes-prep-tasks');
    return null;
  }, [helpOrigin, activeTab]);

  const submitAsk86 = async (question = askQuestion) => {
    const trimmed = String(question || '').trim();
    if (!trimmed) return;
    setAskLoading(true);
    const fallback = makeDeterministicHelpAnswer(trimmed);
    try {
      const response = await secureFetch('/api/help-assistant', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ question: trimmed, history: askHistory.slice(-4).map(turn => ({ role: turn.role, text: turn.text })) })
      });
      const json = await response.json().catch(() => null);
      if (!response.ok || !json?.ok) throw new Error(json?.error || 'help-ai-unavailable');
      const safeArticleIds = (json.sourceArticleIds || []).filter(id => CUSTOMER_HELP_ARTICLES.some(a => a.id === id));
      const safeDeepLinkIds = (json.suggestedDeepLinkIds || []).filter(id => HELP_DEEP_LINKS[id]);
      const result = { ...fallback, ...json, sourceArticleIds: safeArticleIds.length ? safeArticleIds : fallback.sourceArticleIds, suggestedDeepLinkIds: safeDeepLinkIds.length ? safeDeepLinkIds : fallback.suggestedDeepLinkIds, fallbackUsed: false };
      setAskResult(result);
      setAskHistory(prev => [...prev, { role: 'user', text: trimmed }, { role: 'assistant', text: result.answer }].slice(-8));
    } catch (_) {
      setAskResult({ ...fallback, fallbackUsed: true, note: 'Ask 86 used the built-in Help answer because the assistant service was unavailable.' });
      setAskHistory(prev => [...prev, { role: 'user', text: trimmed }, { role: 'assistant', text: fallback.answer }].slice(-8));
      addToast?.('Ask 86 fallback', 'Showing the built-in Help answer.');
    } finally {
      setAskLoading(false);
    }
  };

  const handleBugSubmit = async (e, overrideText = '') => {
    e.preventDefault?.();
    const message = (overrideText || bugText || feedbackText || '').trim();
    if (!message) return;
    setIsSubmittingBug(true);
    try {
      const selected = article || (directAnswer?.sourceArticleIds?.[0] ? CUSTOMER_HELP_ARTICLES.find(a => a.id === directAnswer.sourceArticleIds[0]) : null);
      const response = await secureFetch('/api/report-bug', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          category: bugCategory,
          message,
          user: appUser?.name || 'Unknown',
          userEmail: appUser?.email || '',
          restaurantId: appUser?.restaurantId || 'Unknown',
          restaurantName: appUser?.restaurantName || appUser?.restaurant || '',
          activeTab: helpOrigin || activeTab || 'help',
          helpQuestion: query || askQuestion || '',
          helpArticleId: selected?.id || '',
          helpArticleTitle: selected?.title || '',
          appVersion: CURRENT_VERSION,
          userAgent: navigator.userAgent,
          screenSize: `${window.innerWidth}x${window.innerHeight}`,
          url: window.location.href
        })
      });
      if (!response.ok) throw new Error('report-failed');
      setBugText('');
      setFeedbackText('');
      setFeedbackOpen(false);
      addToast?.('Report Saved', 'Support report saved.');
    } catch (_) {
      addToast?.('Error', 'Failed to send support report.');
    }
    setIsSubmittingBug(false);
  };

  const ArticleCard = ({ a }) => <button type="button" onClick={() => chooseArticle(a.id)} className="bg-[#12161A] border border-[#2A353D] rounded-2xl p-4 text-left hover:border-[#D4A381]/60 focus:outline-none focus:ring-2 focus:ring-[#D4A381] min-h-[96px]">
    <div className="text-[10px] uppercase tracking-widest font-black text-[#D4A381]">{HELP_SUBTOPICS.find(s => s.id === a.subtopicId)?.label || a.subtopicId}</div>
    <div className="font-black text-white mt-1">{a.title}</div>
    <p className="text-xs text-slate-400 font-bold leading-relaxed mt-2">{a.summary}</p>
    <div className="mt-2 text-[9px] uppercase tracking-widest font-black text-slate-500">{a.audience}</div>
  </button>;

  const renderArticle = (a) => <article className={`${T.card} p-5 space-y-4`}>
    <nav aria-label="Help breadcrumbs" className="flex flex-wrap items-center gap-2 text-[10px] uppercase tracking-widest font-black text-slate-500">
      <button type="button" onClick={() => { setSelectedArticleId(''); setSelectedSubtopic(''); setSelectedSubject(''); pushHelpState({ helpSubject: '', helpSubtopic: '', helpArticle: '' }); }} className="hover:text-[#D4A381] focus:outline-none focus:ring-2 focus:ring-[#D4A381] rounded">Help</button>
      <span>›</span><button type="button" onClick={() => chooseSubject(a.subjectId)} className="hover:text-[#D4A381] focus:outline-none focus:ring-2 focus:ring-[#D4A381] rounded">{HELP_SUBJECTS.find(s => s.id === a.subjectId)?.label}</button>
      <span>›</span><button type="button" onClick={() => chooseSubtopic(a.subtopicId)} className="hover:text-[#D4A381] focus:outline-none focus:ring-2 focus:ring-[#D4A381] rounded">{HELP_SUBTOPICS.find(s => s.id === a.subtopicId)?.label}</button>
    </nav>
    <div>
      <div className="text-[10px] uppercase tracking-widest font-black text-[#D4A381]">{a.audience}</div>
      <h3 className="text-2xl font-black text-white mt-1">{a.title}</h3>
      <p className="text-sm text-slate-300 font-bold leading-relaxed mt-2">{a.summary}</p>
    </div>
    {(a.sections || []).map((section, idx) => <section key={idx} className="bg-[#12161A] border border-[#2A353D] rounded-2xl p-4">
      <h4 className="font-black text-white mb-2">{section.title}</h4>
      {(section.body || []).map((line, i) => <p key={`b-${i}`} className="text-sm text-slate-300 font-bold leading-relaxed mb-2"><HelpInlineText text={line} canOpenHelpLink={canOpenHelpLink} openHelpLink={openHelpLink}/></p>)}
      {section.steps?.length ? <ol className="space-y-2">{section.steps.map((line, i) => <li key={i} className="flex gap-3 text-sm text-slate-200 font-bold leading-relaxed"><span className="w-7 h-7 rounded-full bg-[#D4A381] text-slate-900 flex items-center justify-center text-xs font-black shrink-0">{i+1}</span><span><HelpInlineText text={line} canOpenHelpLink={canOpenHelpLink} openHelpLink={openHelpLink}/></span></li>)}</ol> : null}
    </section>)}
    {a.troubleshooting?.length ? <section className="bg-amber-950/20 border border-amber-800/40 rounded-2xl p-4"><h4 className="font-black text-amber-200 mb-2">If it doesn't work</h4><ul className="list-disc pl-5 space-y-1 text-sm text-amber-50/90 font-bold">{a.troubleshooting.map((line, i) => <li key={i}><HelpInlineText text={line} canOpenHelpLink={canOpenHelpLink} openHelpLink={openHelpLink}/></li>)}</ul></section> : null}
    {a.deepLinkIds?.length ? <section className="flex flex-wrap gap-2">{a.deepLinkIds.map(id => {
      const dest = HELP_DEEP_LINKS[id];
      if (!dest) return null;
      const allowed = canOpenHelpLink(id);
      return <button key={id} type="button" onClick={() => openHelpLink(id)} className={`${allowed ? T.btn : T.btnAlt} min-h-[42px]`} aria-disabled={!allowed}>{allowed ? `Open ${dest.label}` : `${dest.label}: manager or owner needed`}</button>;
    })}</section> : null}
    {a.externalLinks?.length ? <section className="bg-[#12161A] border border-[#2A353D] rounded-2xl p-4"><h4 className="font-black text-white mb-2">Helpful external links</h4><div className="flex flex-wrap gap-2">{a.externalLinks.filter(link => /^https:\/\//i.test(link.url || '')).map(link => <a key={link.id || link.url} href={link.url} target="_blank" rel="noopener noreferrer" className={`${T.btnAlt} min-h-[42px] inline-flex items-center gap-2`}>{link.label || 'Open link'} ↗</a>)}</div></section> : null}
    <section className="border-t border-[#2A353D] pt-4">
      <h4 className="font-black text-white mb-2">Still having trouble?</h4>
      <div className="flex flex-wrap gap-2"><button type="button" onClick={() => { setAskQuestion(a.title); submitAsk86(a.title); }} className={T.btnAlt}>Ask another question</button><button type="button" onClick={() => setFeedbackOpen(true)} className={T.btnAlt}>Did this solve your problem?</button><button type="button" onClick={() => setBugCategory('Help Problem')} className={T.btnAlt}>Report a Problem</button></div>
    </section>
  </article>;

  return <div className="desktop-management-page max-w-7xl mx-auto space-y-4 pb-24" data-testid="customer-help-center">
    <div className={`${T.card} p-5 cockpit-grid flex flex-col gap-4`}>
      <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-3">
        <div><div className="text-[10px] uppercase tracking-widest font-black text-[#D4A381]">Customer Help</div><h2 className="text-2xl font-black text-white">Help Center</h2><p className="text-sm text-slate-400 font-bold mt-1 max-w-3xl">Plain-language Help for restaurant users. Internal platform manuals stay in the System Administrator area, not here.</p>{originSubject && <p className="text-xs text-[#D4A381] font-black mt-2">Help with {originSubject.label}</p>}</div>
        <div className="flex flex-wrap gap-2"><button type="button" onClick={() => window.dispatchEvent(new CustomEvent('chaosRestartTour', { detail: { mode: 'employee' } }))} className={T.btnAlt}>Restart Employee Tour</button>{roleIsManager && <button type="button" onClick={() => window.dispatchEvent(new CustomEvent('chaosRestartTour', { detail: { mode: 'manager' } }))} className={T.btn}>Restart Manager Tour</button>}</div>
      </div>
      <form onSubmit={(e) => { e.preventDefault(); setAskQuestion(query); submitAsk86(query); }} className="grid lg:grid-cols-[1fr_auto] gap-2" role="search">
        <label className="sr-only" htmlFor="customer-help-search">What can I help you with?</label>
        <div className="relative"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500"/><input id="customer-help-search" value={query} onChange={e => setQuery(e.target.value)} placeholder="Ask: Why aren't my schedules publishing?" className="w-full bg-[#12161A] border border-[#2A353D] rounded-xl pl-10 pr-3 py-3 min-h-[44px] text-sm font-bold text-white outline-none focus:border-[#D4A381]"/></div>
        <button type="submit" disabled={!query.trim() || askLoading} className={`${T.btn} min-h-[44px] flex items-center justify-center gap-2`}>{askLoading ? <Loader2 className="animate-spin" size={16}/> : <Sparkles size={16}/>} Ask 86</button>
      </form>
    </div>

    {query.trim() && directAnswer && <section className={`${T.card} p-5 border-[#D4A381]/30`} aria-live="polite">
      <div className="text-[10px] uppercase tracking-widest font-black text-[#D4A381]">Direct answer</div>
      <p className="text-lg text-white font-black mt-2 leading-snug"><HelpInlineText text={directAnswer.answer} canOpenHelpLink={canOpenHelpLink} openHelpLink={openHelpLink}/></p>
      <div className="mt-4 grid sm:grid-cols-2 lg:grid-cols-3 gap-2">{searchResults.slice(0, 6).map(a => <ArticleCard key={a.id} a={a}/>)}</div>
    </section>}

    {askResult && <section className={`${T.card} p-5 border-emerald-900/40`} aria-live="polite">
      <div className="flex items-center gap-2 text-[10px] uppercase tracking-widest font-black text-emerald-300"><Sparkles size={14}/> Ask 86 {askResult.fallbackUsed ? 'built-in fallback' : 'answer'}</div>
      <p className="text-sm text-slate-100 font-bold leading-relaxed mt-3"><HelpInlineText text={askResult.answer} canOpenHelpLink={canOpenHelpLink} openHelpLink={openHelpLink}/></p>
      <div className="mt-3"><div className="text-[10px] uppercase tracking-widest font-black text-slate-500 mb-2">Based on</div><div className="flex flex-wrap gap-2">{(askResult.sourceArticleIds || []).map(id => CUSTOMER_HELP_ARTICLES.find(a => a.id === id)).filter(Boolean).map(a => <button type="button" key={a.id} onClick={() => chooseArticle(a.id)} className={T.btnAlt}>{a.title}</button>)}</div></div><div className="mt-3"><div className="text-[10px] uppercase tracking-widest font-black text-slate-500 mb-2">Suggested app links</div><div className="flex flex-wrap gap-2">{(askResult.suggestedDeepLinkIds || []).filter(id => HELP_DEEP_LINKS[id]).map(id => { const dest = HELP_DEEP_LINKS[id]; const allowed = canOpenHelpLink(id); return <button type="button" key={id} onClick={() => openHelpLink(id)} className={`${allowed ? T.btn : T.btnAlt} min-h-[42px]`} aria-disabled={!allowed}>{allowed ? `Open ${dest.label}` : `${dest.label}: manager or owner needed`}</button>; })}</div></div>
      <div className="mt-3 flex gap-2"><input value={askQuestion} onChange={e => setAskQuestion(e.target.value)} maxLength={900} className={`${T.input} min-h-[42px]`} placeholder="Ask a follow-up"/><button type="button" onClick={() => submitAsk86()} className={`${T.btn} min-h-[42px]`}>Ask follow-up</button><button type="button" onClick={() => { setAskHistory([]); setAskResult(null); }} className={`${T.btnAlt} min-h-[42px]`}>Clear</button></div>
    </section>}

    {!selectedSubject && !selectedArticleId && !query.trim() && <section className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3" aria-label="Help subjects">
      {HELP_SUBJECTS.map(s => <button key={s.id} type="button" onClick={() => chooseSubject(s.id)} className="bg-[#12161A] border border-[#2A353D] rounded-2xl p-5 text-left hover:border-[#D4A381]/60 focus:outline-none focus:ring-2 focus:ring-[#D4A381] min-h-[120px]"><div className="text-[10px] uppercase tracking-widest font-black text-[#D4A381]">Subject</div><h3 className="font-black text-white text-lg mt-1">{s.label}</h3><p className="text-xs text-slate-400 font-bold leading-relaxed mt-2">{s.summary}</p></button>)}
    </section>}

    {subject && !subtopic && !article && <section className={`${T.card} p-5 space-y-4`}>
      <button type="button" onClick={() => { setSelectedSubject(''); pushHelpState({ helpSubject: '' }); }} className={`${T.btnAlt} min-h-[42px]`}>Back to Help Home</button>
      <div><div className="text-[10px] uppercase tracking-widest font-black text-[#D4A381]">Help → {subject.label}</div><h3 className="text-2xl font-black text-white mt-1">{subject.label}</h3><p className="text-sm text-slate-400 font-bold mt-1">{subject.summary}</p></div>
      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">{subtopics.map(st => <button key={st.id} type="button" onClick={() => chooseSubtopic(st.id)} className="bg-[#12161A] border border-[#2A353D] rounded-2xl p-4 text-left hover:border-[#D4A381]/60 focus:outline-none focus:ring-2 focus:ring-[#D4A381] min-h-[86px]"><div className="font-black text-white">{st.label}</div><div className="text-xs text-slate-500 font-bold mt-1">{CUSTOMER_HELP_ARTICLES.filter(a => a.subtopicId === st.id).length} article(s)</div></button>)}</div>
    </section>}

    {subtopic && !article && <section className={`${T.card} p-5 space-y-4`}>
      <button type="button" onClick={() => { setSelectedSubtopic(''); pushHelpState({ helpSubtopic: '' }); }} className={`${T.btnAlt} min-h-[42px]`}>Back to {subject?.label || 'Subject'}</button>
      <div><div className="text-[10px] uppercase tracking-widest font-black text-[#D4A381]">Help → {subject?.label} → {subtopic.label}</div><h3 className="text-2xl font-black text-white mt-1">{subtopic.label}</h3></div>
      <div className="grid sm:grid-cols-2 gap-3">{CUSTOMER_HELP_ARTICLES.filter(a => a.subtopicId === subtopic.id).map(a => <ArticleCard key={a.id} a={a}/>)}</div>
    </section>}

    {article && renderArticle(article)}

    <section className="grid lg:grid-cols-2 gap-4">
      <div className={`${T.card} p-4`}>
        <h4 className="font-black text-white mb-2">86 Chaos User Guide</h4>
        <p className="text-xs text-slate-400 font-bold leading-relaxed">This guide is built only from customer Help articles. It does not include internal platform manuals, release-gate notes, customer-management tools, or backend instructions.</p>
        <div className="mt-3 text-[10px] uppercase tracking-widest font-black text-slate-500">{coverage.length} customer areas mapped • {CUSTOMER_HELP_ARTICLES.length} articles</div>
      </div>
      <div className={`${T.card} p-4 border-orange-900/40`}>
        <div className="flex items-center gap-2 mb-2"><Bug size={18} className="text-orange-300"/><h4 className="font-black text-orange-300">Report a Problem</h4></div>
        <p className="text-xs text-slate-400 font-bold mb-3">Tell us what you clicked, what you expected, and what happened. Help context is included safely.</p>
        <form onSubmit={handleBugSubmit} className="space-y-3"><select value={bugCategory} onChange={e=>setBugCategory(e.target.value)} className={`${T.input} py-2 text-sm min-h-[42px]`}><option>Bug / Error</option><option>Feature Request</option><option>Login Problem</option><option>Permission Problem</option><option>Data Looks Wrong</option><option>Mobile Layout Problem</option><option>Help Problem</option></select><textarea value={bugText} onChange={e=>setBugText(e.target.value)} className={T.input} rows="4" placeholder="Example: I searched schedule publishing but still could not find the button." required></textarea><button type="submit" disabled={isSubmittingBug || !bugText.trim()} className={`w-full ${T.btn} disabled:opacity-50 flex items-center justify-center gap-2 min-h-[44px]`}>{isSubmittingBug ? <Loader2 className="animate-spin" size={18}/> : <><Send size={18}/> Send Support Report</>}</button></form>
      </div>
    </section>

    {feedbackOpen && <Modal isOpen={feedbackOpen} onClose={() => setFeedbackOpen(false)} title="Did this solve your problem?">
      <div className="space-y-3"><div className="flex gap-2"><button type="button" onClick={() => { setFeedbackOpen(false); addToast?.('Thanks', 'Glad it helped.'); }} className={`${T.btn} flex-1 min-h-[44px]`}>Yes</button><button type="button" onClick={() => setFeedbackText('')} className={`${T.btnAlt} flex-1 min-h-[44px]`}>No</button></div><textarea value={feedbackText} onChange={e => setFeedbackText(e.target.value)} className={T.input} rows="4" placeholder="Tell us what you were trying to do."/><button type="button" disabled={!feedbackText.trim()} onClick={(e) => handleBugSubmit(e, `Help feedback: ${feedbackText.trim()}`)} className={`${T.btn} w-full min-h-[44px]`}>Send Feedback</button></div>
    </Modal>}
  </div>;
};


const TabFinancials = ({ currentDate, users = [], shifts = [], sales = [], timePunches = [], addToast, appUser, clientData = {}, setActiveTab, initialSubTab = 'overview' }) => {
  const canSales = financeAccess(appUser, 'sales');
  const canLabor = financeAccess(appUser, 'labor');
  const planAccess = usePlanAccess(appUser, clientData);
  const [subTab, setSubTab] = useState(initialSubTab === 'ledger' ? 'daily-close' : initialSubTab === 'labor' ? 'labor' : initialSubTab || 'overview');
  const [month, setMonth] = useState(getMonthStr(currentDate || getToday()));
  const [expenseForm, setExpenseForm] = useState({ date: getToday(), vendor: '', category: 'Other', amount: '', paymentMethod: 'Unpaid', dueDate: '', paid: false, notes: '' });
  const [targetsDraft, setTargetsDraft] = useState(DEFAULT_FINANCE_TARGETS);

  const canLaborCommand = planAccess.canUse(FEATURE_KEYS.LABOR_COMMAND).allowed || planAccess.canUse(FEATURE_KEYS.TIMESHEETS).allowed;
  const canSmartFinancials = planAccess.canUse(FEATURE_KEYS.FINANCIAL_OVERVIEW).allowed || planAccess.canUse(FEATURE_KEYS.COGS_CENTER).allowed;
  const canExpenses = planAccess.canUse(FEATURE_KEYS.EXPENSES).allowed;
  const canTargets = planAccess.canUse(FEATURE_KEYS.BUDGET_TARGETS).allowed;
  const canInvoiceData = planAccess.canUse(FEATURE_KEYS.INVOICE_TOTALS).allowed || planAccess.canUse(FEATURE_KEYS.COGS_CENTER).allowed;
  const dbRoles = useLiveCollection('roles', appUser?.restaurantId, { enabled: !!appUser?.restaurantId && canLaborCommand, limitCount: 250 });
  const financialExpenses = useLiveCollection('financialExpenses', appUser?.restaurantId, { enabled: !!appUser?.restaurantId && canSales && canExpenses, limitCount: 250, fallbackLimitCount: 150 });
  const financialTargets = useLiveCollection('financialTargets', appUser?.restaurantId, { enabled: !!appUser?.restaurantId && canSales && canTargets, limitCount: 25, fallbackLimitCount: 25 });
  const invoices = useLiveCollection('invoices', appUser?.restaurantId, { enabled: !!appUser?.restaurantId && canSales && canInvoiceData, limitCount: 250, fallbackLimitCount: 150 });

  const rosterRoleOptions = Array.from(new Map([
    ...dbRoles.map(r => normalizeLaborRole(r.name)),
    ...users.filter(u => u.isActive !== false).map(u => normalizeLaborRole(u.role))
  ].filter(Boolean).map(role => [roleFilterKey(role), role])).values()).sort((a, b) => a.localeCompare(b));

  const monthStart = `${month}-01`;
  const monthEnd = `${month}-${String(getDaysInMonth(month)).padStart(2, '0')}`;
  const monthSales = sales.filter(s => safeFinanceDate(s) >= monthStart && safeFinanceDate(s) <= monthEnd);
  const monthPunches = timePunches.filter(p => (p.date || '') >= monthStart && (p.date || '') <= monthEnd);
  const monthExpenses = financialExpenses.filter(e => safeFinanceDate(e) >= monthStart && safeFinanceDate(e) <= monthEnd);
  const monthInvoices = invoices.filter(inv => safeFinanceDate(inv) >= monthStart && safeFinanceDate(inv) <= monthEnd);
  const targetRecord = financialTargets[0] || null;
  const targets = { ...DEFAULT_FINANCE_TARGETS, ...(targetRecord || {}) };

  useEffect(() => {
    setTargetsDraft({ ...DEFAULT_FINANCE_TARGETS, ...(targetRecord || {}) });
  }, [targetRecord?.id, targetRecord?.updatedAt]);

  const activeUsers = users.filter(u => u.isActive !== false);
  const userForPunch = (p) => users.find(u => u.id === p.employeeId) || {};
  const payrollRows = monthPunches.map(p => {
    const emp = userForPunch(p);
    const hours = calculatePunchHours(p.clockInTime, p.clockOutTime, p.breakMinutes || 0);
    return { punch: p, emp, role: normalizeLaborRole(emp.role), hours, pay: hours * parseFinanceAmount(emp.wage), tips: parseFinanceAmount(p.cashTips) + parseFinanceAmount(p.creditTips), issue: ['clocked_in','on_break'].includes(p.status) || !p.clockOutTime || hours > 12 || p.requiresManagerReview };
  });
  const grossSales = monthSales.reduce((sum, s) => sum + getFinancialGrossSales(s), 0);
  const netSales = monthSales.reduce((sum, s) => sum + getFinancialNetSales(s), 0);
  const laborCost = payrollRows.reduce((sum, row) => sum + row.pay, 0) || monthSales.reduce((sum, s) => sum + getFinancialLaborCost(s), 0);
  const foodCost = monthSales.reduce((sum, s) => sum + getFinancialFoodCost(s), 0);
  const beverageCost = monthSales.reduce((sum, s) => sum + getFinancialBeverageCost(s), 0);
  const operatingExpenses = monthExpenses.reduce((sum, e) => sum + getFinancialExpenseAmount(e), 0);
  const invoiceSpend = monthInvoices.reduce((sum, inv) => sum + getFinancialInvoiceAmount(inv), 0);
  const totalTips = payrollRows.reduce((sum, row) => sum + row.tips, 0);
  const openPayrollIssues = payrollRows.filter(row => row.issue).length;
  const cashVariance = monthSales.reduce((sum, s) => sum + parseFinanceAmount(s.cashVariance), 0);
  const depositsPending = monthSales.filter(s => !['Deposited', 'Verified'].includes(String(s.depositStatus || '')) && getFinancialGrossSales(s) > 0).length;
  const missingCloseDays = Array.from({ length: getDaysInMonth(month) }).map((_, i) => `${month}-${String(i + 1).padStart(2, '0')}`).filter(date => new Date(date + 'T12:00:00') <= new Date() && !monthSales.some(s => s.date === date)).length;
  const primeCost = laborCost + foodCost + beverageCost;
  const laborPct = netSales > 0 ? (laborCost / netSales) * 100 : 0;
  const foodPct = netSales > 0 ? (foodCost / netSales) * 100 : 0;
  const beveragePct = netSales > 0 ? (beverageCost / netSales) * 100 : 0;
  const primePct = netSales > 0 ? (primeCost / netSales) * 100 : 0;
  const estimatedProfit = netSales - primeCost - operatingExpenses;

  const roleBreakdown = rosterRoleOptions.map(role => {
    const key = roleFilterKey(role);
    const rows = payrollRows.filter(row => roleFilterKey(row.role) === key);
    return { role, hours: rows.reduce((s, r) => s + r.hours, 0), pay: rows.reduce((s, r) => s + r.pay, 0), tips: rows.reduce((s, r) => s + r.tips, 0), issues: rows.filter(r => r.issue).length };
  }).filter(row => row.hours > 0 || row.pay > 0 || row.tips > 0);

  const salesMix = FINANCE_SALES_CATEGORIES.map(([key, label]) => ({ label, value: monthSales.reduce((sum, s) => sum + parseFinanceAmount(s[key]), 0) })).filter(row => row.value > 0);
  const expenseBreakdown = FINANCE_EXPENSE_CATEGORIES.map(category => ({ category, amount: monthExpenses.filter(e => e.category === category).reduce((s, e) => s + getFinancialExpenseAmount(e), 0) })).filter(row => row.amount > 0);
  const vendorSpend = Object.entries(monthInvoices.reduce((acc, inv) => {
    const name = inv.vendorName || inv.vendor || inv.supplier || 'Unassigned vendor';
    acc[name] = (acc[name] || 0) + getFinancialInvoiceAmount(inv);
    return acc;
  }, {})).map(([vendor, amount]) => ({ vendor, amount })).sort((a, b) => b.amount - a.amount);

  const financeTabs = [
    { id: 'overview', label: 'Overview', show: canSales || canLabor, access: planAccess.canFinancialSubtab('overview') },
    { id: 'daily-close', label: 'Daily Close', show: canSales, access: planAccess.canFinancialSubtab('daily-close') },
    { id: 'sales', label: 'Sales', show: canSales, access: planAccess.canFinancialSubtab('ledger') },
    { id: 'labor', label: 'Labor & Payroll', show: canLabor, access: planAccess.canFinancialSubtab('labor') },
    { id: 'tips', label: 'Tips', show: canLabor, access: planAccess.canFinancialSubtab('tips') },
    { id: 'cogs', label: 'COGS & Vendors', show: canSales, access: planAccess.canFinancialSubtab('cogs') },
    { id: 'expenses', label: 'Expenses', show: canSales, access: planAccess.canFinancialSubtab('expenses') },
    { id: 'pnl', label: 'P&L', show: canSales, access: planAccess.canFinancialSubtab('pnl') },
    { id: 'targets', label: 'Targets', show: canSales, access: planAccess.canFinancialSubtab('targets') },
    { id: 'reports', label: 'Reports', show: canSales || canLabor, access: planAccess.canFinancialSubtab('reports') }
  ].filter(t => t.show);
  const selectedFinanceTab = financeTabs.find(t => t.id === subTab) || financeTabs[0];
  const selectedFinanceAccess = selectedFinanceTab?.access;

  useEffect(() => {
    if (!financeTabs.some(t => t.id === subTab) && financeTabs[0]) setSubTab(financeTabs[0].id);
  }, [canSales, canLabor, subTab, planAccess.subscription.planId]);

  const saveExpense = async (e) => {
    e.preventDefault();
    if (!expenseForm.vendor.trim()) return addToast('Vendor Needed', 'Enter a vendor or payee for this expense.');
    if (parseFinanceAmount(expenseForm.amount) <= 0) return addToast('Amount Needed', 'Enter an expense amount greater than zero.');
    const payload = {
      ...expenseForm,
      vendor: expenseForm.vendor.trim(),
      amount: parseFinanceAmount(expenseForm.amount),
      paid: expenseForm.paid === true || expenseForm.paymentMethod !== 'Unpaid',
      restaurantId: appUser.restaurantId,
      createdAt: new Date().toISOString(),
      createdBy: appUser.name || appUser.email || 'Manager',
      updatedAt: new Date().toISOString()
    };
    try {
      const refObj = await addDoc(collection(db, 'financialExpenses'), payload);
      await logAudit(appUser, 'FINANCIAL_EXPENSE_CREATED', `financialExpenses/${refObj.id}`, `Added ${moneyText(payload.amount, 2)} expense for ${payload.vendor}`);
      setExpenseForm({ date: getToday(), vendor: '', category: 'Other', amount: '', paymentMethod: 'Unpaid', dueDate: '', paid: false, notes: '' });
      addToast('Expense Saved', 'Expense added to Financial Center.');
    } catch (err) { addToast('Error', err.message); }
  };

  const deleteExpense = async (expense) => {
    if (!window.confirm(`Delete ${expense.vendor || 'this expense'} for ${moneyText(expense.amount, 2)}?`)) return;
    try {
      await deleteDoc(doc(db, 'financialExpenses', expense.id));
      await logAudit(appUser, 'FINANCIAL_EXPENSE_DELETED', `financialExpenses/${expense.id}`, `Deleted expense ${expense.vendor || ''}`);
      addToast('Expense Deleted', 'Expense removed.');
    } catch (err) { addToast('Error', err.message); }
  };

  const saveTargets = async (e) => {
    e.preventDefault();
    const payload = {
      ...Object.fromEntries(Object.entries(targetsDraft).map(([key, value]) => [key, parseFinanceAmount(value)])),
      restaurantId: appUser.restaurantId,
      updatedAt: new Date().toISOString(),
      updatedBy: appUser.name || appUser.email || 'Manager'
    };
    try {
      await setDoc(doc(db, 'financialTargets', appUser.restaurantId), payload, { merge: true });
      await logAudit(appUser, 'FINANCIAL_TARGETS_UPDATED', `financialTargets/${appUser.restaurantId}`, 'Updated Financial Center targets');
      addToast('Targets Saved', 'Financial goals and warning thresholds updated.');
    } catch (err) { addToast('Error', err.message); }
  };

  const reportPrefix = getRestaurantExportPrefix(appUser, '86chaos');
  const downloadFinanceReport = (type = 'overview') => {
    const rows = [
      ['Metric', 'Value'],
      ['Month', formatDisplayMonth(month)],
      ['Gross Sales', moneyText(grossSales, 2)],
      ['Net Sales', moneyText(netSales, 2)],
      ['Labor Cost', moneyText(laborCost, 2)],
      ['Labor %', pctText(laborPct)],
      ['Food Cost', moneyText(foodCost, 2)],
      ['Food %', pctText(foodPct)],
      ['Beverage Cost', moneyText(beverageCost, 2)],
      ['Prime Cost %', pctText(primePct)],
      ['Operating Expenses', moneyText(operatingExpenses, 2)],
      ['Invoice Spend', moneyText(invoiceSpend, 2)],
      ['Estimated Profit', moneyText(estimatedProfit, 2)],
      ['Cash Variance', moneyText(cashVariance, 2)],
      ['Open Payroll Issues', openPayrollIssues],
      ['Pending Deposits', depositsPending],
      ['Missing Daily Closes', missingCloseDays]
    ];
    if (type === 'csv') downloadCsvRows(`${reportPrefix}_financial_center_${month}.csv`, rows);
    else openPrintableReport({ title: 'Financial Center Report', subtitle: `${formatDisplayMonth(month)} • ${appUser?.restaurantName || appUser?.restaurant || 'Restaurant'}`, rows, filename: `${reportPrefix}_financial_center_${month}` });
  };

  const downloadTipsReport = () => {
    const rows = [['Employee', 'Roster Role', 'Hours', 'Cash Tips', 'Credit Tips', 'Total Tips'], ...activeUsers.map(user => {
      const rows = monthPunches.filter(p => p.employeeId === user.id);
      const hours = rows.reduce((s, p) => s + calculatePunchHours(p.clockInTime, p.clockOutTime, p.breakMinutes || 0), 0);
      const cash = rows.reduce((s, p) => s + parseFinanceAmount(p.cashTips), 0);
      const credit = rows.reduce((s, p) => s + parseFinanceAmount(p.creditTips), 0);
      return [user.name || user.email || 'Employee', normalizeLaborRole(user.role), hours.toFixed(2), cash.toFixed(2), credit.toFixed(2), (cash + credit).toFixed(2)];
    }).filter(row => parseFinanceAmount(row[2]) || parseFinanceAmount(row[5]))];
    downloadCsvRows(`${reportPrefix}_tips_${month}.csv`, rows);
  };

  const Metric = ({ label, value, helper, tone = 'text-white' }) => (
    <div className="bg-[#12161A] border border-[#2A353D] rounded-2xl p-4">
      <div className="text-xs uppercase tracking-widest font-black text-slate-400">{label}</div>
      <div className={`text-2xl font-black mt-1 ${tone}`}>{value}</div>
      {helper && <div className="text-xs text-slate-400 font-bold mt-1 leading-relaxed">{helper}</div>}
    </div>
  );

  const SimpleTable = ({ headers, rows, empty = 'No records found.' }) => (
    <div className={`${T.card} overflow-hidden`}>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead className="bg-[#12161A] text-slate-300"><tr>{headers.map(h => <th key={h} className="text-left p-3 font-black whitespace-nowrap">{h}</th>)}</tr></thead>
          <tbody className="divide-y divide-[#2A353D]">
            {rows.length === 0 && <tr><td colSpan={headers.length} className="p-6 text-center text-slate-400 font-bold">{empty}</td></tr>}
            {rows.map((row, idx) => <tr key={idx} className="hover:bg-[#12161A]/60">{row.map((cell, i) => <td key={i} className="p-3 text-slate-200 align-top whitespace-nowrap">{cell}</td>)}</tr>)}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className="financial-center-desktop max-w-7xl mx-auto space-y-4 pb-24">
      <div className={`${T.card} p-5 cockpit-grid`}>
        <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-4">
          <div>
            <div className="text-xs font-black uppercase tracking-widest text-[#D4A381] mb-1">Financial Center</div>
            <h2 className="text-3xl font-black text-white tracking-tight">Professional Financial Center</h2>
            <p className="text-sm text-slate-300 font-bold mt-2 max-w-4xl">Daily close, sales mix, labor, tips, COGS, expenses, P&L, targets, and owner-ready reports in one readable command center. Role views use the custom Roster Roles created in Preferences.</p>
          </div>
          <div className="flex flex-wrap gap-2 items-center">
            <input type="month" value={month} onChange={e => setMonth(e.target.value)} className={`${T.input} w-auto`}/>
            <button onClick={() => downloadFinanceReport('print')} className={T.btnAlt}>Print Report</button>
          </div>
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto pb-2 border-b border-[#2A353D] custom-scrollbar">
        {financeTabs.map(tab => <button key={tab.id} onClick={() => setSubTab(tab.id)} className={`px-4 py-3 rounded-xl text-xs uppercase tracking-widest font-black whitespace-nowrap ${subTab === tab.id ? `${T.grad} text-slate-900` : 'bg-[#1A2126] text-slate-300 hover:text-white border border-[#2A353D]'} ${tab.access?.allowed ? '' : 'opacity-75'}`}>{tab.access?.allowed ? tab.label : `🔒 ${tab.label}`}</button>)}
      </div>

      {selectedFinanceAccess && selectedFinanceAccess.allowed === false && (
        <LockedFeatureScreen access={selectedFinanceAccess} appUser={appUser} setActiveTab={setActiveTab} />
      )}

      {selectedFinanceAccess?.allowed !== false && subTab === 'overview' && (
        <div className="space-y-4">
          <div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-3">
            <Metric label="Net Sales" value={moneyText(netSales)} helper={`${monthSales.length} daily close records`} tone="text-[#D4A381]" />
            <Metric label="Prime Cost" value={pctText(primePct)} helper={`${moneyText(primeCost)} labor + food + beverage`} tone={primePct > targets.primePct ? 'text-red-400' : 'text-emerald-400'} />
            <Metric label="Estimated Profit" value={moneyText(estimatedProfit)} helper="Net sales minus prime cost and expenses" tone={estimatedProfit < 0 ? 'text-red-400' : 'text-emerald-400'} />
            <Metric label="Cash Variance" value={moneyText(cashVariance, 2)} helper={`${depositsPending} pending deposits`} tone={Math.abs(cashVariance) > parseFinanceAmount(targets.cashVarianceAlert) ? 'text-red-400' : 'text-emerald-400'} />
          </div>
          <div className="grid lg:grid-cols-3 gap-4">
            <div className={`${T.card} p-4 lg:col-span-2`}>
              <h3 className="font-black text-white text-xl mb-3">Financial Health</h3>
              <div className="grid sm:grid-cols-3 gap-3">
                <Metric label="Labor" value={pctText(laborPct)} helper={`Target ${pctText(targets.laborPct)}`} tone={laborPct > targets.laborPct ? 'text-red-400' : 'text-emerald-400'} />
                <Metric label="Food" value={pctText(foodPct)} helper={`Target ${pctText(targets.foodPct)}`} tone={foodPct > targets.foodPct ? 'text-red-400' : 'text-emerald-400'} />
                <Metric label="Beverage" value={pctText(beveragePct)} helper={`Target ${pctText(targets.beveragePct)}`} tone={beveragePct > targets.beveragePct ? 'text-red-400' : 'text-emerald-400'} />
              </div>
            </div>
            <div className={`${T.card} p-4`}>
              <h3 className="font-black text-white text-xl mb-3">Needs Attention</h3>
              <div className="space-y-2 text-sm font-bold">
                <div className="flex justify-between gap-3"><span className="text-slate-400">Open payroll issues</span><span className={openPayrollIssues ? 'text-red-400' : 'text-emerald-400'}>{openPayrollIssues}</span></div>
                <div className="flex justify-between gap-3"><span className="text-slate-400">Missing daily closes</span><span className={missingCloseDays ? 'text-orange-300' : 'text-emerald-400'}>{missingCloseDays}</span></div>
                <div className="flex justify-between gap-3"><span className="text-slate-400">Deposits pending</span><span className={depositsPending ? 'text-orange-300' : 'text-emerald-400'}>{depositsPending}</span></div>
                <div className="flex justify-between gap-3"><span className="text-slate-400">Expenses unpaid</span><span className={monthExpenses.filter(e => !e.paid && e.paymentMethod === 'Unpaid').length ? 'text-orange-300' : 'text-emerald-400'}>{monthExpenses.filter(e => !e.paid && e.paymentMethod === 'Unpaid').length}</span></div>
              </div>
            </div>
          </div>
          <SimpleTable headers={['Roster Role', 'Hours', 'Labor Cost', 'Tips', 'Issues']} rows={roleBreakdown.map(r => [r.role, r.hours.toFixed(2), moneyText(r.pay, 2), moneyText(r.tips, 2), r.issues])} empty="No labor by role for this month yet. Role names come from Preferences > Roster Roles." />
        </div>
      )}

      {selectedFinanceAccess?.allowed !== false && subTab === 'daily-close' && <TabSales sales={sales} timePunches={timePunches} users={users} addToast={addToast} appUser={appUser} />}

      {selectedFinanceAccess?.allowed !== false && subTab === 'sales' && (
        <div className="grid lg:grid-cols-2 gap-4">
          <div className={`${T.card} p-4`}><h3 className="font-black text-white text-xl mb-3">Sales Mix</h3><div className="space-y-3">{salesMix.length === 0 && <FriendlyEmpty title="No sales mix yet" text="Enter category sales in Daily Close to unlock mix reporting."/>}{salesMix.map(row => <div key={row.label}><div className="flex justify-between text-sm font-black"><span className="text-white">{row.label}</span><span className="text-[#D4A381]">{moneyText(row.value, 2)}</span></div><div className="h-2 bg-[#0B0E11] border border-[#2A353D] rounded-full mt-1 overflow-hidden"><div className="h-full bg-[#D4A381]" style={{ width: `${Math.min(100, netSales > 0 ? (row.value / netSales) * 100 : 0)}%` }} /></div></div>)}</div></div>
          <SimpleTable headers={['Date', 'Gross', 'Net', 'Cash', 'Card', 'Deposit', 'Status']} rows={monthSales.sort((a,b) => safeFinanceDate(a).localeCompare(safeFinanceDate(b))).map(s => [formatDisplayDate(safeFinanceDate(s)), moneyText(getFinancialGrossSales(s), 2), moneyText(getFinancialNetSales(s), 2), moneyText(s.cashSales, 2), moneyText(s.cardSales, 2), moneyText(s.depositAmount, 2), s.closeStatus || 'Open'])} />
        </div>
      )}

      {selectedFinanceAccess?.allowed !== false && subTab === 'labor' && <TabLabor currentDate={currentDate} users={users} shifts={shifts} sales={sales} timePunches={timePunches} addToast={addToast} appUser={appUser} />}

      {selectedFinanceAccess?.allowed !== false && subTab === 'tips' && (
        <div className="space-y-4">
          <div className="grid sm:grid-cols-3 gap-3"><Metric label="Total Tips" value={moneyText(totalTips, 2)} helper="Cash + credit tips on time punches" tone="text-[#D4A381]"/><Metric label="Tip Records" value={monthPunches.filter(p => parseFinanceAmount(p.cashTips) || parseFinanceAmount(p.creditTips)).length} helper="Punches with declared tips"/><Metric label="Export" value="Ready" helper="CSV tip report by employee and roster role" tone="text-emerald-400"/></div>
          <button onClick={downloadTipsReport} className={T.btn}>Download Tip Report</button>
          <SimpleTable headers={['Employee', 'Roster Role', 'Hours', 'Cash Tips', 'Credit Tips', 'Total']} rows={activeUsers.map(user => { const rows = monthPunches.filter(p => p.employeeId === user.id); const hours = rows.reduce((s,p)=>s+calculatePunchHours(p.clockInTime,p.clockOutTime,p.breakMinutes||0),0); const cash = rows.reduce((s,p)=>s+parseFinanceAmount(p.cashTips),0); const credit = rows.reduce((s,p)=>s+parseFinanceAmount(p.creditTips),0); return [user.name || user.email || 'Employee', normalizeLaborRole(user.role), hours.toFixed(2), moneyText(cash,2), moneyText(credit,2), moneyText(cash+credit,2)]; }).filter(row => parseFinanceAmount(row[2]) || row[5] !== moneyText(0,2))} />
        </div>
      )}

      {selectedFinanceAccess?.allowed !== false && subTab === 'cogs' && (
        <div className="grid lg:grid-cols-2 gap-4">
          <div className="space-y-3"><Metric label="Invoice Spend" value={moneyText(invoiceSpend, 2)} helper="From invoice history in the selected month" tone="text-[#D4A381]"/><Metric label="Food + Beverage Cost" value={moneyText(foodCost + beverageCost, 2)} helper={`${pctText(netSales > 0 ? ((foodCost + beverageCost) / netSales) * 100 : 0)} of net sales`} tone={(foodPct + beveragePct) > (targets.foodPct + targets.beveragePct) ? 'text-red-400' : 'text-emerald-400'} /><Metric label="Unreviewed invoices" value={monthInvoices.filter(inv => ['Needs Review','Draft','Pending'].includes(String(inv.status || ''))).length} helper="Finish reconciliation in Inventory" /></div>
          <SimpleTable headers={['Vendor', 'Spend']} rows={vendorSpend.map(v => [v.vendor, moneyText(v.amount, 2)])} empty="No invoice vendor spend found for this month." />
        </div>
      )}

      {selectedFinanceAccess?.allowed !== false && subTab === 'expenses' && (
        <div className="grid lg:grid-cols-3 gap-4">
          <form onSubmit={saveExpense} className={`${T.card} p-4 space-y-3`}><h3 className="text-xl font-black text-white">Add Expense</h3><label className={T.label}>Date</label><input type="date" value={expenseForm.date} onChange={e=>setExpenseForm({...expenseForm,date:e.target.value})} className={T.input}/><label className={T.label}>Vendor / Payee</label><input value={expenseForm.vendor} onChange={e=>setExpenseForm({...expenseForm,vendor:e.target.value})} className={T.input} placeholder="Utility company, repair tech, supplier..."/><label className={T.label}>Category</label><select value={expenseForm.category} onChange={e=>setExpenseForm({...expenseForm,category:e.target.value})} className={T.input}>{FINANCE_EXPENSE_CATEGORIES.map(c=><option key={c}>{c}</option>)}</select><label className={T.label}>Amount</label><input type="number" min="0" step="0.01" value={expenseForm.amount} onChange={e=>setExpenseForm({...expenseForm,amount:e.target.value})} className={T.input}/><label className={T.label}>Payment Method</label><select value={expenseForm.paymentMethod} onChange={e=>setExpenseForm({...expenseForm,paymentMethod:e.target.value,paid:e.target.value!=='Unpaid'})} className={T.input}>{FINANCE_PAYMENT_METHODS.map(c=><option key={c}>{c}</option>)}</select><label className={T.label}>Due Date</label><input type="date" value={expenseForm.dueDate} onChange={e=>setExpenseForm({...expenseForm,dueDate:e.target.value})} className={T.input}/><label className={T.label}>Notes</label><textarea value={expenseForm.notes} onChange={e=>setExpenseForm({...expenseForm,notes:e.target.value})} className={T.input} rows={3}></textarea><button className={`${T.btn} w-full`}>Save Expense</button></form>
          <div className="lg:col-span-2 space-y-4"><div className="grid sm:grid-cols-2 gap-3"><Metric label="Operating Expenses" value={moneyText(operatingExpenses, 2)} helper={`${monthExpenses.length} expense records`} tone="text-[#D4A381]"/><Metric label="Unpaid" value={moneyText(monthExpenses.filter(e=>!e.paid && e.paymentMethod==='Unpaid').reduce((s,e)=>s+getFinancialExpenseAmount(e),0),2)} helper="Marked Unpaid" tone="text-orange-300"/></div><SimpleTable headers={['Date','Vendor','Category','Amount','Method','Due','']} rows={monthExpenses.sort((a,b)=>safeFinanceDate(b).localeCompare(safeFinanceDate(a))).map(e => [formatDisplayDate(safeFinanceDate(e)), e.vendor || e.payee || 'Expense', e.category || 'Other', moneyText(e.amount,2), e.paymentMethod || (e.paid ? 'Paid' : 'Unpaid'), e.dueDate || '', <button onClick={() => deleteExpense(e)} className="text-red-300 hover:text-red-200 font-black">Delete</button>])} /></div>
        </div>
      )}

      {selectedFinanceAccess?.allowed !== false && subTab === 'pnl' && (
        <div className="grid lg:grid-cols-2 gap-4">
          <SimpleTable headers={['Line', 'Amount']} rows={[
            ['Gross Sales', moneyText(grossSales, 2)], ['Less Discounts / Comps / Refunds', moneyText(grossSales - netSales, 2)], ['Net Sales', moneyText(netSales, 2)], ['Food Cost', moneyText(foodCost, 2)], ['Beverage Cost', moneyText(beverageCost, 2)], ['Gross Profit', moneyText(netSales - foodCost - beverageCost, 2)], ['Labor', moneyText(laborCost, 2)], ['Operating Expenses', moneyText(operatingExpenses, 2)], ['Estimated Net Profit', moneyText(estimatedProfit, 2)]
          ]} />
          <div className={`${T.card} p-4`}><h3 className="font-black text-white text-xl mb-3">P&L Notes</h3><p className="text-sm text-slate-300 font-bold leading-relaxed">This is an operational P&L snapshot, not tax accounting. It uses entered Daily Close numbers, time punches, invoices, and expenses saved in 86 Chaos. Use it to manage the restaurant week-to-week, then reconcile against your accountant or POS/accounting system.</p><div className="mt-4 grid sm:grid-cols-2 gap-3"><Metric label="Gross Profit" value={moneyText(netSales - foodCost - beverageCost, 2)} /><Metric label="Net Profit" value={moneyText(estimatedProfit, 2)} tone={estimatedProfit < 0 ? 'text-red-400' : 'text-emerald-400'} /></div></div>
        </div>
      )}

      {selectedFinanceAccess?.allowed !== false && subTab === 'targets' && (
        <form onSubmit={saveTargets} className={`${T.card} p-5 space-y-4 max-w-5xl`}><h3 className="text-2xl font-black text-white">Financial Targets & Warning Thresholds</h3><p className="text-sm text-slate-300 font-bold">Targets drive the dashboard color signals. Set realistic numbers for this restaurant, not generic industry mythology.</p><div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">{Object.entries({ laborPct:'Target Labor %', foodPct:'Target Food %', beveragePct:'Target Beverage %', primePct:'Target Prime %', weeklySalesGoal:'Weekly Sales Goal', monthlySalesGoal:'Monthly Sales Goal', cashVarianceAlert:'Cash Variance Alert', overtimeAlertHours:'Overtime Alert Hours' }).map(([key,label]) => <label key={key}><span className="block text-xs font-black text-slate-300 mb-1">{label}</span><input type="number" step="0.01" value={targetsDraft[key] ?? ''} onChange={e=>setTargetsDraft({...targetsDraft,[key]:e.target.value})} className={T.input}/></label>)}</div><button className={T.btn}>Save Targets</button></form>
      )}

      {selectedFinanceAccess?.allowed !== false && subTab === 'reports' && (
        <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-4">{[
          ['Owner Financial Report', 'Printable month summary with KPIs, risks, P&L, and close status.', () => downloadFinanceReport('print')],
          ['CSV Financial Summary', 'Download the same high-level report as a spreadsheet-friendly CSV.', () => downloadFinanceReport('csv')],
          ['Tip Report', 'Employee tips by roster role for payroll review.', downloadTipsReport],
          ['Payroll Detail', 'Use Labor & Payroll > Export for punch-level CSV or print-ready PDF.', () => setSubTab('labor')],
          ['Daily Close Review', 'Open Daily Close to save or print individual closeout worksheets.', () => setSubTab('daily-close')],
          ['COGS & Vendor Spend', 'Review invoice totals and vendor spend before ordering or budgeting.', () => setSubTab('cogs')]
        ].map(([title, desc, action]) => <button key={title} onClick={action} className={`${T.card} p-5 text-left hover:border-[#D4A381]/60 transition-colors`}><h3 className="text-lg font-black text-white">{title}</h3><p className="text-sm text-slate-400 font-bold mt-2 leading-relaxed">{desc}</p></button>)}</div>
      )}
    </div>
  );
};


const TabBackOffice = ({ currentDate, users = [], sales = [], timePunches = [], restaurantAdminAlerts = [], appUser, clientData = {}, setActiveTab, addToast }) => {
  const restaurantId = appUser?.restaurantId || clientData?.id || clientData?.restaurantId;
  const planAccess = usePlanAccess(appUser, clientData);
  const backOfficeAccess = planAccess.canUse(FEATURE_KEYS.BACK_OFFICE_SUITE);
  const quickBooksAccess = planAccess.canUse(FEATURE_KEYS.QUICKBOOKS_INTEGRATION);
  const [subTab, setSubTab] = useState('dashboard');
  const [depositForm, setDepositForm] = useState({ date: getToday(), cashSales: '', cardSales: '', tipsPaid: '', payouts: '', depositAmount: '', drawerVariance: '', closedBy: appUser?.name || '', notes: '' });
  const [documentForm, setDocumentForm] = useState({ title: '', category: 'License / Permit', expiresAt: '', location: '', notes: '' });
  const [documentFile, setDocumentFile] = useState(null);
  const [documentBusyId, setDocumentBusyId] = useState('');
  const [approvalForm, setApprovalForm] = useState({ title: '', category: 'Owner Review', priority: 'normal', requestedBy: appUser?.name || '', notes: '' });
  const [qbMapping, setQbMapping] = useState({ bankAccount: '', accountsPayable: '', salesIncome: '', tipsPayable: '', cashOverShort: '', foodPurchases: '', beveragePurchases: '', supplies: '', cogs: '', taxAccount: '', classTracking: 'off', defaultClass: '', defaultLocation: '', foodClass: '', beverageClass: '', suppliesClass: '', salesClass: '', taxAgency: '', memoTemplate: '86 Chaos {month} {vendor} {number}', exportBasis: 'accrual' });
  const [qbCreditForm, setQbCreditForm] = useState({ vendorName: '', creditDate: getToday(), amount: '', invoiceNumber: '', reason: '', account: 'Food Purchases' });
  const [qbPacketForm, setQbPacketForm] = useState({ closeMonth: getToday().slice(0, 7), preparedBy: appUser?.name || appUser?.email || '', accountantEmail: '', notes: '' });
  const [qbStatus, setQbStatus] = useState({ checking: false, configured: false, message: 'Not connected. QuickBooks sync is owner-approved and safe by default.' });
  const [webhookStatus, setWebhookStatus] = useState({ checking: false, message: 'Webhook receiver scaffold is ready for setup check.' });
  const [syncHealth, setSyncHealth] = useState({ checking: false, score: null, message: 'Phase 3 sync health check has not run yet.' });

  const records = useLiveCollection('backOfficeRecords', restaurantId, { enabled: !!restaurantId && backOfficeAccess.allowed, limitCount: 350, fallbackLimitCount: 150 });
  const invoices = useLiveCollection('invoices', restaurantId, { enabled: !!restaurantId && backOfficeAccess.allowed && quickBooksAccess.allowed, limitCount: 150, fallbackLimitCount: 80 });
  const vendors = useLiveCollection('vendors', restaurantId, { enabled: !!restaurantId && backOfficeAccess.allowed && quickBooksAccess.allowed, limitCount: 150, fallbackLimitCount: 80 });
  const deposits = records.filter(r => r.type === 'deposit').sort((a,b) => String(b.date || b.createdAt || '').localeCompare(String(a.date || a.createdAt || '')));
  const documents = records.filter(r => r.type === 'document').sort((a,b) => String(a.expiresAt || '9999').localeCompare(String(b.expiresAt || '9999')));
  const approvals = records.filter(r => r.type === 'approval').sort((a,b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
  const qbRecords = records.filter(r => ['quickbooks', 'quickbooks_mapping', 'quickbooks_bill_draft', 'quickbooks_vendor_match', 'quickbooks_vendor_credit_draft', 'quickbooks_sync_event', 'quickbooks_accountant_packet', 'quickbooks_owner_rollup', 'quickbooks_sync_health'].includes(r.type));
  const qbBillDrafts = qbRecords.filter(r => r.type === 'quickbooks_bill_draft');
  const qbVendorMatches = qbRecords.filter(r => r.type === 'quickbooks_vendor_match' && !['dismissed', 'inactive'].includes(String(r.status || '').toLowerCase()));
  const qbVendorCredits = qbRecords.filter(r => r.type === 'quickbooks_vendor_credit_draft');
  const qbRepairQueue = qbRecords.filter(r => ['sync_failed', 'needs_mapping', 'needs_credentials', 'retry_ready', 'draft_needs_review', 'send_blocked'].includes(String(r.status || '').toLowerCase()));
  const openAlerts = (restaurantAdminAlerts || []).filter(a => !['resolved', 'dismissed'].includes(String(a.status || 'open').toLowerCase()));
  const openApprovals = approvals.filter(a => !['approved', 'dismissed', 'done'].includes(String(a.status || 'pending').toLowerCase()));
  const stamp = () => Timestamp.now();
  const vendorKey = (value = '') => String(value || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
  const simpleKey = (value = '') => vendorKey(value).replace(/\b(inc|llc|ltd|co|company|foods|foodservice|distributing|distributor|sysco|pfg)\b/g, '').replace(/\s+/g, ' ').trim();
  const moneyValue = (value) => Number(parseFinanceAmount(value) || 0);
  const invoiceAmount = (invoice) => moneyValue(invoice.invoiceTotal || invoice.grandTotal || invoice.total || invoice.amount);
  const invoiceDate = (invoice) => invoice.invoiceDate || invoice.date || invoice.processedAt || getToday();
  const existingBillDraftInvoiceIds = new Set(qbBillDrafts.map(r => String(r.invoiceId || '')).filter(Boolean));
  const sortedInvoices = invoices.slice().sort((a,b) => String(invoiceDate(b)).localeCompare(String(invoiceDate(a))));
  const unmappedInvoiceVendors = Array.from(new Set(sortedInvoices.map(inv => inv.vendorName || inv.vendor || '').filter(Boolean))).filter(name => !qbVendorMatches.some(m => vendorKey(m.vendorAlias) === vendorKey(name)));

  const month = (currentDate || getToday()).slice(0, 7);
  const monthSales = (sales || []).filter(s => safeFinanceDate(s).startsWith(month));
  const netSales = monthSales.reduce((sum, item) => sum + getFinancialNetSales(item), 0);
  const depositTotal = deposits.filter(d => String(d.date || '').startsWith(month)).reduce((sum, d) => sum + parseFinanceAmount(d.depositAmount), 0);
  const cashVariance = deposits.filter(d => String(d.date || '').startsWith(month)).reduce((sum, d) => sum + parseFinanceAmount(d.drawerVariance), 0);
  const expiringDocs = documents.filter(d => d.expiresAt && new Date(d.expiresAt).getTime() - Date.now() < 45 * 86400000 && new Date(d.expiresAt).getTime() >= Date.now());
  const closeMonth = qbPacketForm.closeMonth || month;
  const recordMonth = (record = {}) => String(record.invoiceDate || record.creditDate || record.closeMonth || record.date || record.createdAt?.toDate?.()?.toISOString?.() || record.createdAt || '').slice(0, 7);
  const qbMonthlyRecords = qbRecords.filter(r => recordMonth(r) === closeMonth);
  const qbMonthlyBillDrafts = qbBillDrafts.filter(r => recordMonth(r) === closeMonth);
  const qbMonthlyCredits = qbVendorCredits.filter(r => recordMonth(r) === closeMonth);
  const qbDraftTotal = qbMonthlyBillDrafts.reduce((sum, r) => sum + moneyValue(r.invoiceTotal), 0);
  const qbCreditTotal = qbMonthlyCredits.reduce((sum, r) => sum + moneyValue(r.amount), 0);
  const qbReadyRecords = qbRecords.filter(r => ['ready_to_send', 'retry_ready', 'draft_needs_review'].includes(String(r.status || '').toLowerCase()));
  const qbBlockedRecords = qbRecords.filter(r => ['needs_mapping', 'needs_credentials', 'sync_failed', 'send_blocked'].includes(String(r.status || '').toLowerCase()));
  const qbMappingMissing = ['accountsPayable', 'bankAccount', 'salesIncome', 'foodPurchases', 'beveragePurchases', 'supplies', 'cashOverShort'].filter(key => !String(qbMapping[key] || '').trim());
  const qbSuggestedMappings = [
    ['Accounts Payable', qbMapping.accountsPayable || 'Accounts Payable'],
    ['Bank / Deposit Account', qbMapping.bankAccount || 'Undeposited Funds'],
    ['Sales Income', qbMapping.salesIncome || 'Sales'],
    ['Tips Payable', qbMapping.tipsPayable || 'Tips Payable'],
    ['Cash Over / Short', qbMapping.cashOverShort || 'Cash Over and Short'],
    ['Food Purchases', qbMapping.foodPurchases || 'Food Purchases'],
    ['Beverage Purchases', qbMapping.beveragePurchases || 'Beverage Purchases'],
    ['Supplies', qbMapping.supplies || 'Supplies'],
    ['COGS', qbMapping.cogs || 'Cost of Goods Sold']
  ];
  const qbCloseReadiness = Math.max(0, Math.min(100, 100 - (qbMappingMissing.length * 10) - (unmappedInvoiceVendors.length * 5) - (qbBlockedRecords.length * 4)));
  const workspaceRoster = Array.isArray(appUser?.workspaces) ? appUser.workspaces : Array.isArray(appUser?.restaurants) ? appUser.restaurants : [];
  const ownerLocationRows = [{ name: clientData?.name || appUser?.restaurantName || 'Current workspace', restaurantId, netSales, depositTotal, cashVariance, openAlerts: openAlerts.length, qbDrafts: qbBillDrafts.length, repairQueue: qbRepairQueue.length }].concat(workspaceRoster.filter(w => String(w?.id || w?.restaurantId || '') !== String(restaurantId || '')).slice(0, 12).map(w => ({ name: w.name || w.restaurantName || w.label || w.id || 'Workspace', restaurantId: w.id || w.restaurantId || '', netSales: '', depositTotal: '', cashVariance: '', openAlerts: '', qbDrafts: '', repairQueue: 'Open workspace to load live totals' })));

  if (!backOfficeAccess.allowed) return <LockedFeatureScreen access={backOfficeAccess} appUser={appUser} setActiveTab={setActiveTab} />;

  const resolveVendorMatch = (vendorName = '') => {
    const key = vendorKey(vendorName);
    const short = simpleKey(vendorName);
    const saved = qbVendorMatches.find(m => vendorKey(m.vendorAlias) === key || vendorKey(m.vendorName) === key || simpleKey(m.vendorAlias) === short);
    if (saved) return { id: saved.vendorId || '', name: saved.vendorName || saved.vendorAlias || vendorName, source: 'saved match' };
    const exact = vendors.find(v => vendorKey(v.name) === key || simpleKey(v.name) === short);
    if (exact) return { id: exact.id, name: exact.name, source: 'exact vendor' };
    const fuzzy = vendors.find(v => short && (simpleKey(v.name).includes(short) || short.includes(simpleKey(v.name))));
    if (fuzzy) return { id: fuzzy.id, name: fuzzy.name, source: 'suggested vendor' };
    return { id: '', name: vendorName || 'Unknown Vendor', source: 'needs mapping' };
  };

  const categoryAccountForLine = (line = {}) => {
    const text = String([line.category, line.classificationCategory, line.scannerClassification, line.itemName, line.name, line.description].filter(Boolean).join(' ')).toLowerCase();
    if (/beer|wine|liquor|beverage|soda|syrup|coffee|tea/.test(text)) return qbMapping.beveragePurchases || 'Beverage Purchases';
    if (/napkin|foil|container|box|bag|cup|lid|straw|clean|chemical|glove|paper|supply|supplies/.test(text)) return qbMapping.supplies || 'Supplies';
    return qbMapping.foodPurchases || qbMapping.cogs || 'Food Purchases';
  };

  const classLocationForLine = (line = {}) => {
    const text = String([line.category, line.classificationCategory, line.scannerClassification, line.itemName, line.name, line.description].filter(Boolean).join(' ')).toLowerCase();
    const className = /beer|wine|liquor|beverage|soda|syrup|coffee|tea/.test(text) ? qbMapping.beverageClass : /napkin|foil|container|box|bag|cup|lid|straw|clean|chemical|glove|paper|supply|supplies/.test(text) ? qbMapping.suppliesClass : qbMapping.foodClass;
    return { className: className || qbMapping.defaultClass || '', locationName: qbMapping.defaultLocation || '' };
  };

  const buildQuickBooksBillDraft = (invoice = {}) => {
    const vendorMatch = resolveVendorMatch(invoice.vendorName || invoice.vendor || '');
    const rawLines = Array.isArray(invoice.lineItems) ? invoice.lineItems : [];
