        fileMimeType: file.type || '',
        fileSize: Number(file.size || 0),
        uploadedAt: stamp(),
        uploadedBy,
        uploadedByName: appUser?.name || appUser?.email || 'Owner/Admin',
        uploadStatus: 'uploaded',
        vaultFilePurpose: 'document-vault',
